 const expandedBank=[{"topic":"Human Anatomy & Physiology","q":["Which blood component is primarily responsible for oxygen transport?","अक्सिजन बोक्ने मुख्य रक्तकोष कुन हो?",["Red blood cells","Platelets","Neutrophils","Plasma proteins"],0,"Haemoglobin in red blood cells binds and transports most oxygen.","Red blood cell भित्रको haemoglobin ले धेरैजसो अक्सिजन बोकेर लैजान्छ।"]},{"topic":"Human Anatomy & Physiology","q":["Which part of the brain helps coordinate voluntary movement and balance?","स्वेच्छिक चाल र सन्तुलन मिलाउन मस्तिष्कको कुन भागले मद्दत गर्छ?",["Cerebellum","Medulla","Hypothalamus","Thalamus"],0,"The cerebellum coordinates movement, posture and balance.","Cerebellum ले चाल, posture र सन्तुलन मिलाउँछ।"]},{"topic":"Human Anatomy & Physiology","q":["Which chamber pumps oxygenated blood into the aorta?","Aorta मा अक्सिजनयुक्त रगत कुन chamber ले पठाउँछ?",["Left ventricle","Right ventricle","Right atrium","Left atrium"],0,"The left ventricle pumps oxygenated blood into systemic circulation through the aorta.","Left ventricle ले aorta हुँदै शरीरमा अक्सिजनयुक्त रगत पठाउँछ।"]},{"topic":"Human Anatomy & Physiology","q":["Which organ produces insulin?","Insulin कुन अंगले उत्पादन गर्छ?",["Pancreas","Liver","Kidney","Spleen"],0,"Beta cells in the pancreatic islets produce insulin.","Pancreas को islets का beta cells ले insulin बनाउँछन्।"]},{"topic":"Human Anatomy & Physiology","q":["Which type of joint is the shoulder joint?","Shoulder joint कुन प्रकारको joint हो?",["Ball-and-socket synovial joint","Hinge joint","Pivot joint","Fixed fibrous joint"],0,"The shoulder is a ball-and-socket synovial joint allowing movement in multiple directions.","Shoulder ball-and-socket synovial joint हो, जसले धेरै दिशामा चाल दिन्छ।"]},{"topic":"Human Anatomy & Physiology","q":["What is the functional unit of the kidney?","मिर्गौलाको functional unit कुन हो?",["Nephron","Alveolus","Neuron","Hepatocyte"],0,"The nephron filters blood and contributes to urine formation.","Nephron ले रगत filter गरी पिसाब बन्ने प्रक्रियामा काम गर्छ।"]},{"topic":"Oral Anatomy & Physiology","q":["Which tooth tissue is the hardest in the human body?","मानव शरीरको सबैभन्दा कडा दाँतको tissue कुन हो?",["Enamel","Dentin","Cementum","Pulp"],0,"Enamel is the highly mineralized outer covering of the anatomical crown.","Enamel दाँतको crown ढाक्ने अत्यधिक mineralized र सबैभन्दा कडा tissue हो।"]},{"topic":"Oral Anatomy & Physiology","q":["Which teeth are primarily designed for tearing food?","खाना च्यात्न मुख्यतः कुन दाँत बनिएका हुन्छन्?",["Canines","Incisors","Molars","Premolars"],0,"Canines have a pointed cusp and assist in tearing food.","Canine मा pointed cusp हुन्छ र खाना च्यात्न मद्दत गर्छ।"]},{"topic":"Oral Anatomy & Physiology","q":["Which salivary gland produces most resting saliva?","आराम अवस्थामा धेरै saliva कुन gland ले बनाउँछ?",["Submandibular gland","Parotid gland","Sublingual gland","Minor labial glands"],0,"The submandibular glands contribute the largest share of unstimulated resting saliva.","Resting अवस्थामा submandibular gland ले सबैभन्दा धेरै saliva दिन्छ।"]},{"topic":"Oral Anatomy & Physiology","q":["The temporomandibular joint connects the mandible with which bone?","Temporomandibular joint ले mandible लाई कुन हड्डीसँग जोड्छ?",["Temporal bone","Maxilla","Zygomatic bone","Frontal bone"],0,"The mandibular condyle articulates with the temporal bone.","Mandibular condyle ले temporal bone सँग articulation गर्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["A white oral lesion that cannot be wiped off requires assessment for:","पुछ्दा नहट्ने सेतो oral lesion भए केको मूल्याङ्कन आवश्यक हुन्छ?",["Leukoplakia and other potentially significant lesions","Normal plaque only","Dental fluorosis","Salivary stone"],0,"A persistent non-scrapable white lesion needs professional examination and appropriate diagnosis.","नहट्ने सेतो घाउको सही diagnosis का लागि professional examination आवश्यक हुन्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["Which feature is typical of an acute inflammatory response?","Acute inflammation को सामान्य विशेषता कुन हो?",["Redness, heat, swelling and pain","Tooth eruption only","Enamel formation","Cementum deposition"],0,"Acute inflammation commonly produces redness, heat, swelling, pain and sometimes loss of function.","Acute inflammation मा रातोपन, ताप, सुन्निनु र दुखाइ देखिन सक्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["What is the main role of normal oral microbiota?","सामान्य oral microbiota को मुख्य भूमिका के हो?",["Help maintain microbial balance and colonization resistance","Cause disease in every person","Dissolve all enamel","Stop saliva production"],0,"Normal microbiota can help limit pathogen overgrowth, although imbalance may contribute to disease.","सामान्य microbiota ले हानिकारक जीवको अत्यधिक वृद्धि रोक्न मद्दत गर्न सक्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Which route gives a medicine directly into the bloodstream?","औषधि सिधै रक्तप्रवाहमा पुर्‍याउने route कुन हो?",["Intravenous","Oral","Topical","Subcutaneous"],0,"Intravenous administration delivers medicine directly into a vein.","Intravenous route बाट औषधि सिधै नसामा दिइन्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["What should be checked before administering a prescribed medicine?","Prescribed औषधि दिनुअघि के जाँच गर्नुपर्छ?",["Patient identity, allergy, medicine, dose and route","Only package colour","Only medicine price","Only patient's occupation"],0,"Medication safety includes confirming the patient, allergy status, medicine, dose, route and timing.","औषधि सुरक्षा लागि बिरामी, allergy, औषधि, dose, route र समय जाँच्नुपर्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Which drug group is commonly used to reduce bacterial infection when clinically indicated?","आवश्यक clinical indication हुँदा bacterial infection घटाउन कुन औषधि समूह प्रयोग हुन्छ?",["Antibiotics","Antacids","Antihistamines","Antifungals only"],0,"Antibiotics act against susceptible bacteria and should be used only when indicated and prescribed appropriately.","Antibiotics संवेदनशील bacteria विरुद्ध काम गर्छन् र आवश्यकताअनुसार मात्र प्रयोग गर्नुपर्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["A medicine's contraindication means:","औषधिको contraindication भन्नाले के बुझिन्छ?",["A condition in which the medicine should not be used","The medicine's colour","The medicine's expiry date","A preferred flavour"],0,"A contraindication is a patient condition or circumstance in which a medicine may cause harm or should be avoided.","Contraindication भनेको औषधि दिँदा हानि हुन सक्ने वा नदिनुपर्ने अवस्था हो।"]},{"topic":"Basic Periodontology I","q":["What is the main purpose of disclosing solution?","Disclosing solution को मुख्य उद्देश्य के हो?",["Make dental plaque visible","Remove calculus chemically","Measure pocket depth","Test pulp vitality"],0,"Disclosing agents stain plaque and help patients identify areas needing better cleaning.","Disclosing agent ले plaque देखिने बनाउँछ र सफा गर्न छुटेका भाग पहिचान गर्न मद्दत गर्छ।"]},{"topic":"Basic Periodontology I","q":["Which brushing method is commonly recommended for effective gingival margin cleaning?","Gingival margin सफा गर्न कुन brushing method प्रायः सिफारिस गरिन्छ?",["Modified Bass technique","Horizontal scrubbing with excessive force","No brushing near gingiva","Only chewing-side brushing"],0,"Modified Bass uses gentle bristle placement near the gingival sulcus with small vibratory movements and a roll.","Modified Bass मा brush लाई gingival margin नजिक राखेर हल्का vibratory र roll movement गरिन्छ।"]},{"topic":"Basic Periodontology I","q":["What is the purpose of an explorer during periodontal assessment?","Periodontal assessment मा explorer को काम के हो?",["Detect deposits and surface irregularities tactually","Measure blood pressure","Measure tooth mobility quantitatively","Take radiographs"],0,"An explorer helps detect calculus and surface irregularities by tactile sensation.","Explorer ले छामेर calculus र सतहका अनियमितता पत्ता लगाउन मद्दत गर्छ।"]},{"topic":"Basic Periodontology I","q":["Which finding is most consistent with gingival recession?","Gingival recession सँग कुन finding मिल्छ?",["Apical displacement of the gingival margin","Coronal movement of the gingival margin","Increased enamel thickness","Pulp chamber enlargement"],0,"Gingival recession is the apical displacement of the gingival margin exposing more root surface.","Gingival recession मा gingival margin तलतिर सरेर root surface बढी देखिन्छ।"]},{"topic":"Basic Periodontology I","q":["Why should ultrasonic scaler tips be kept moving?","Ultrasonic scaler tip चलाइराख्नु किन आवश्यक छ?",["To reduce heat and avoid surface damage","To increase pressure on one point","To intentionally cut enamel","To stop water flow"],0,"Continuous controlled movement with adequate irrigation reduces heat buildup and tissue or tooth damage.","पर्याप्त पानीसहित tip चलाइराख्दा ताप र दाँत वा tissue क्षति घट्छ।"]},{"topic":"Basic Periodontology I","q":["What is the purpose of periodontal charting?","Periodontal charting को उद्देश्य के हो?",["Record periodontal findings systematically","Record only tooth shade","Replace patient consent","Measure saliva pH only"],0,"A periodontal chart records probing depths, recession, bleeding, mobility and other relevant findings over time.","Periodontal chart मा probing depth, recession, bleeding, mobility लगायतका finding क्रमबद्ध राखिन्छ।"]},{"topic":"Basic Periodontology II","q":["Clinical attachment level is measured from the:","Clinical attachment level कुन बिन्दुबाट मापन गरिन्छ?",["Cemento-enamel junction to the base of the pocket","Incisal edge to gingival margin only","Root apex to crown tip","Occlusal surface to pulp chamber"],0,"Clinical attachment level relates the pocket base to a fixed landmark, usually the cemento-enamel junction.","Clinical attachment level मा pocket base र स्थिर landmark, सामान्यतया CEJ, बीचको दूरी मापन हुन्छ।"]},{"topic":"Basic Periodontology II","q":["Which radiographic change may be seen in periodontitis?","Periodontitis मा radiograph मा कुन परिवर्तन देखिन सक्छ?",["Alveolar bone loss","Enamel thickening","Pulp enlargement in every tooth","Crown lengthening"],0,"Periodontitis may produce horizontal or vertical alveolar bone loss on radiographs.","Periodontitis मा radiograph मा horizontal वा vertical alveolar bone loss देखिन सक्छ।"]},{"topic":"Basic Periodontology II","q":["A periodontal abscess commonly presents with:","Periodontal abscess मा सामान्यतया के देखिन्छ?",["Localized swelling and pain near a periodontal pocket","Painless enamel opacity only","Normal gingiva without symptoms","Pulp chamber calcification only"],0,"A periodontal abscess is a localized infection in periodontal tissues and may cause swelling, pain and suppuration.","Periodontal abscess periodontal tissue को स्थानीय infection हो; सुन्निनु, दुखाइ र pus आउन सक्छ।"]},{"topic":"Basic Periodontology II","q":["Which factor is a well-established modifier of periodontitis risk?","Periodontitis को जोखिम परिवर्तन गर्ने प्रमाणित factor कुन हो?",["Tobacco smoking","Eye colour","Hair length","Hand dominance"],0,"Tobacco smoking is an important modifiable risk factor associated with periodontitis severity and treatment response.","धूम्रपान periodontitis को गम्भीरता र उपचारको नतिजासँग सम्बन्धित परिवर्तन गर्न सकिने risk factor हो।"]},{"topic":"Basic Periodontology II","q":["What is the main goal of supportive periodontal care?","Supportive periodontal care को मुख्य लक्ष्य के हो?",["Maintain periodontal stability and detect recurrence early","Guarantee that disease never returns","Replace all home care","Avoid reassessment"],0,"Supportive care combines periodic reassessment, professional maintenance and reinforcement of self-care.","Supportive care ले नियमित पुनःजाँच, professional maintenance र घरको care सुधार गर्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Which material is commonly used as a liner or base in deep cavities due to its therapeutic properties?","Deep cavity मा therapeutic गुणका कारण कुन material liner वा base का रूपमा प्रयोग हुन सक्छ?",["Calcium hydroxide","Impression compound","Alginate","Zinc oxide impression paste only"],0,"Calcium hydroxide has traditionally been used in selected deep-cavity situations for its high pH and pulp-protective properties.","Calcium hydroxide को उच्च pH का कारण केही deep cavity मा pulp protection का लागि प्रयोग गरिन्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["What is the purpose of a matrix band during restoration?","Restoration गर्दा matrix band को उद्देश्य के हो?",["Recreate a temporary wall and contour","Etch enamel","Measure pocket depth","Remove pulp tissue"],0,"A matrix band helps form the missing proximal wall and contour while restorative material is placed.","Matrix band ले restoration राख्दा हराएको proximal wall र contour बनाउन मद्दत गर्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Which instrument is used to condense amalgam?","Amalgam compact गर्न कुन instrument प्रयोग गरिन्छ?",["Amalgam condenser","Burnisher only","Periodontal probe","Mouth mirror"],0,"An amalgam condenser compacts amalgam into the prepared cavity.","Amalgam condenser ले तयार cavity भित्र amalgam compact गर्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["What is the purpose of a wedge with a matrix system?","Matrix system मा wedge को काम के हो?",["Adapt the matrix at the gingival margin and help separation","Polish enamel","Remove caries","Measure occlusion"],0,"A wedge adapts the matrix at the gingival margin, helps prevent overhangs and may provide slight separation.","Wedge ले gingival margin मा matrix मिलाउँछ, overhang रोक्न र हल्का separation दिन मद्दत गर्छ।"]},{"topic":"Dental Radiography & Photography","q":["What is the main purpose of a lead apron where required by local radiation-safety guidance?","स्थानीय radiation-safety निर्देशनअनुसार आवश्यक हुँदा lead apron को मुख्य उद्देश्य के हो?",["Reduce unnecessary exposure to body tissues","Improve image sharpness","Increase beam intensity","Sterilize the receptor"],0,"Protective shielding is used according to current local guidance and the ALARA principle; it does not replace proper technique.","Shielding स्थानीय निर्देशन र ALARA सिद्धान्तअनुसार प्रयोग हुन्छ; यसले सही technique को विकल्प लिँदैन।"]},{"topic":"Dental Radiography & Photography","q":["A radiograph that is too dark may result from:","धेरै dark radiograph कुन कारणले हुन सक्छ?",["Excessive exposure","Insufficient exposure only","Incorrect patient name","Low room temperature only"],0,"Excessive receptor exposure can produce an image that appears too dark, depending on the imaging system.","अत्यधिक receptor exposure ले imaging system अनुसार radiograph धेरै dark देखिन सक्छ।"]},{"topic":"Dental Radiography & Photography","q":["What does the paralleling technique aim to achieve?","Paralleling technique को उद्देश्य के हो?",["Place receptor parallel to the long axis of the tooth","Place receptor perpendicular to the floor in every case","Avoid using a positioning device","Direct the beam away from the receptor"],0,"The receptor is positioned parallel to the tooth's long axis and the beam is directed perpendicular to both.","Receptor लाई दाँतको long axis सँग parallel राखी beam दुवैप्रति perpendicular गरिन्छ।"]},{"topic":"Dental Radiography & Photography","q":["Which error can cause overlapped proximal contacts?","Proximal contact overlap हुने radiographic error कुन हो?",["Incorrect horizontal angulation","Excessive vertical angulation only","Patient wearing a bib","Low room lighting"],0,"Incorrect horizontal angulation causes the x-ray beam to pass obliquely through proximal contacts.","गलत horizontal angulation हुँदा beam proximal contact बीचबाट सही दिशामा जाँदैन र overlap हुन्छ।"]},{"topic":"Basic Medical Procedure & First Aid","q":["What is the first priority when approaching an unresponsive patient?","प्रतिक्रिया नदिने बिरामी भेट्दा पहिलो प्राथमिकता के हो?",["Ensure scene safety and assess responsiveness","Give oral water immediately","Move the patient without assessment","Start dental treatment"],0,"Ensure the scene is safe, assess responsiveness and activate emergency help according to protocol.","पहिले स्थान सुरक्षित छ कि छैन हेरी प्रतिक्रिया जाँच्ने र protocol अनुसार emergency help बोलाउने।"]},{"topic":"Basic Medical Procedure & First Aid","q":["Which vital sign measures the number of heartbeats per minute?","प्रति मिनेट मुटुको धड्कन मापन गर्ने vital sign कुन हो?",["Pulse rate","Respiratory rate","Temperature","Blood glucose"],0,"Pulse rate records the number of arterial pulsations per minute.","Pulse rate ले एक मिनेटमा हुने arterial pulsation को संख्या जनाउँछ।"]},{"topic":"Basic Medical Procedure & First Aid","q":["What is an appropriate initial response to a fainting episode in the dental chair?","Dental chair मा बेहोस हुने अवस्था आए प्रारम्भिक उपयुक्त कदम के हो?",["Stop treatment, place supine with legs elevated if appropriate, and assess ABCs","Continue treatment quickly","Give food while unconscious","Ask the patient to stand immediately"],0,"Stop the procedure, position the patient safely, assess airway, breathing and circulation, and seek help as needed.","उपचार रोक्ने, सुरक्षित position मा राख्ने, ABC जाँच्ने र आवश्यक परे सहयोग बोलाउने।"]},{"topic":"Dental Public Health & Community Dentistry","q":["What is the main purpose of a school oral-health programme?","विद्यालय oral-health programme को मुख्य उद्देश्य के हो?",["Improve oral health through education, prevention and referral","Provide cosmetic treatment only","Replace all dental clinics","Focus only on adult patients"],0,"School programmes combine age-appropriate education, preventive measures, screening and referral pathways.","विद्यालय कार्यक्रमले उमेरअनुसार शिक्षा, रोकथाम, screening र referral समेट्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["Which is an example of primary prevention in oral health?","मुख स्वास्थ्यमा primary prevention को उदाहरण कुन हो?",["Community water fluoridation where appropriate","Extraction of a non-restorable tooth","Treatment of an established abscess","Rehabilitation after tooth loss"],0,"Primary prevention aims to prevent disease before it develops; fluoride exposure is one example.","Primary prevention ले रोग सुरु हुनुअघि रोक्छ; fluoride exposure यसको उदाहरण हो।"]},{"topic":"Dental Public Health & Community Dentistry","q":["What does DMFT index measure in permanent dentition?","Permanent dentition मा DMFT index ले के मापन गर्छ?",["Decayed, missing due to caries and filled teeth","Gingival bleeding only","Tooth mobility only","Oral cancer stages"],0,"DMFT summarizes the number of decayed, missing due to caries and filled permanent teeth.","DMFT ले caries का कारण बिग्रेका, झरेका र भरिएका permanent दाँतको संख्या जोड्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["Why is community participation important in health programmes?","स्वास्थ्य कार्यक्रममा community participation किन महत्त्वपूर्ण हुन्छ?",["It improves relevance, ownership and sustainability","It removes the need for planning","It guarantees zero disease","It replaces trained health workers"],0,"Participation helps programmes reflect local needs and strengthens community ownership.","सहभागिताले कार्यक्रमलाई स्थानीय आवश्यकतासँग मिलाउँछ र समुदायको अपनत्व बढाउँछ।"]},{"topic":"Health Education","q":["Which method is most suitable for teaching a small group a practical toothbrushing skill?","सानो समूहलाई brushing सीप सिकाउन कुन विधि उपयुक्त हुन्छ?",["Demonstration followed by return demonstration","A long technical lecture only","Silent distribution of leaflets only","No interaction"],0,"Demonstration and return demonstration allow learners to observe and practise the skill.","Demonstration र return demonstration ले सिक्ने व्यक्तिलाई हेर्न र अभ्यास गर्न दिन्छ।"]},{"topic":"Health Education","q":["What should be identified before planning a health-education session?","Health education session योजना बनाउनुअघि के पहिचान गर्नुपर्छ?",["Learners' needs and learning objectives","The speaker's favourite topic only","The most expensive venue","The number of posters alone"],0,"Needs assessment and clear objectives guide relevant content and evaluation.","Needs assessment र स्पष्ट objective ले उपयुक्त content र मूल्याङ्कन तय गर्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["Incidence refers to:","Incidence भन्नाले के बुझिन्छ?",["New cases occurring in a population over a specified period","All existing cases at one point only","Deaths from all causes only","Number of hospital beds"],0,"Incidence measures new cases arising in a population during a defined time period.","Incidence ले निश्चित अवधिमा जनसंख्यामा देखा परेका नयाँ case मापन गर्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["Prevalence includes:","Prevalence मा के समावेश हुन्छ?",["All existing cases in a population at a specified time or period","Only new cases","Only fatal cases","Only cases treated in hospitals"],0,"Prevalence describes the total burden of existing disease in a population at a given time or period.","Prevalence ले निश्चित समयमा वा अवधिमा रहेका सबै विद्यमान रोगका case जनाउँछ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["A case definition is used to:","Case definition किन प्रयोग गरिन्छ?",["Apply consistent criteria to identify cases","Choose treatment prices","Select clinic furniture","Calculate staff salaries"],0,"A standard case definition improves consistency when identifying and counting cases.","Standard case definition ले case पहिचान र गणना एकरूप बनाउँछ।"]},{"topic":"Office Health Management","q":["Why should dental instruments and materials be checked before a clinical session?","Clinical session अघि dental instrument र material किन जाँच्नुपर्छ?",["To confirm readiness, safety and availability","To increase appointment duration","To avoid maintaining records","To replace sterilization monitoring"],0,"Pre-session checks help ensure equipment is functional, supplies are available and care can be delivered safely.","पहिले जाँच गर्दा उपकरण चल्ने, सामग्री उपलब्ध र उपचार सुरक्षित हुने सुनिश्चित गर्न मद्दत हुन्छ।"]},{"topic":"Office Health Management","q":["Which record is important for tracking sterilizer performance?","Sterilizer को performance track गर्न कुन record महत्त्वपूर्ण हुन्छ?",["Sterilization cycle and monitoring log","Patient birthday list only","Daily menu","Staff leave calendar only"],0,"Cycle records and physical, chemical and biological monitoring documentation support traceability and quality assurance.","Cycle record तथा physical, chemical र biological monitoring ले traceability र quality assurance दिन्छ।"]},{"topic":"Environmental Health","q":["Which practice helps prevent cross-contamination from clinical waste?","Clinical waste बाट cross-contamination रोक्न कुन अभ्यासले मद्दत गर्छ?",["Segregate and dispose of waste according to policy","Mix all waste in one open bin","Reuse single-use sharps","Leave waste uncovered"],0,"Waste segregation at the point of generation and safe disposal reduce exposure risks.","Waste निस्कने ठाउँमै छुट्याएर policy अनुसार सुरक्षित व्यवस्थापन गर्दा जोखिम घट्छ।"]},{"topic":"Food & Nutrition","q":["Which nutrient is essential for normal collagen formation and wound healing?","Collagen निर्माण र घाउ निको हुन कुन nutrient आवश्यक हुन्छ?",["Vitamin C","Vitamin D only","Sodium","Caffeine"],0,"Vitamin C is required for collagen synthesis and supports wound healing.","Vitamin C collagen synthesis का लागि आवश्यक हुन्छ र घाउ निको हुन सहयोग गर्छ।"]}];
 const nextExpandedBank=[{"topic":"Human Anatomy & Physiology","q":["Which hormone lowers blood glucose concentration?","रगतमा glucose को मात्रा घटाउने hormone कुन हो?",["Insulin","Glucagon","Adrenaline","Cortisol"],0,"Insulin promotes glucose uptake and storage, lowering blood glucose.","Insulin ले glucose को uptake र storage बढाएर रगतको glucose घटाउँछ।"]},{"topic":"Human Anatomy & Physiology","q":["Which blood cells are primarily involved in clot formation?","रगत जम्ने प्रक्रियामा मुख्य भूमिका कुन रक्तकोषको हुन्छ?",["Platelets","Erythrocytes","Lymphocytes","Monocytes"],0,"Platelets aggregate and support formation of the haemostatic plug.","Platelets एकत्रित भएर haemostatic plug बनाउन सहयोग गर्छन्।"]},{"topic":"Human Anatomy & Physiology","q":["Which structure carries air from the larynx toward the bronchi?","Larynx बाट bronchi तर्फ हावा लैजाने संरचना कुन हो?",["Trachea","Oesophagus","Aorta","Ureter"],0,"The trachea conducts air from the larynx and divides into the main bronchi.","Trachea ले larynx बाट हावा लगेर मुख्य bronchi मा विभाजन गर्छ।"]},{"topic":"Human Anatomy & Physiology","q":["Which part of the nervous system controls many involuntary activities?","धेरै अनैच्छिक क्रियाकलाप नियन्त्रण गर्ने nervous system को भाग कुन हो?",["Autonomic nervous system","Somatic sensory system","Visual cortex only","Motor end plate"],0,"The autonomic nervous system regulates functions such as heart rate and digestion.","Autonomic nervous system ले मुटुको गति र पाचनजस्ता कार्य नियमन गर्छ।"]},{"topic":"Human Anatomy & Physiology","q":["Which organ is the major site of detoxification and metabolism of many drugs?","धेरै औषधिको metabolism र detoxification हुने मुख्य अंग कुन हो?",["Liver","Spleen","Thyroid","Urinary bladder"],0,"The liver contains enzyme systems that metabolize many medicines and toxins.","Liver मा धेरै औषधि र toxin को metabolism गर्ने enzyme system हुन्छ।"]},{"topic":"Oral Anatomy & Physiology","q":["How many permanent teeth are normally present in a complete adult dentition including third molars?","Third molar सहित पूर्ण adult dentition मा सामान्यतया कति स्थायी दाँत हुन्छन्?",["32","20","28","24"],0,"A complete permanent dentition including all third molars contains 32 teeth.","सबै third molar सहित पूर्ण स्थायी dentition मा ३२ दाँत हुन्छन्।"]},{"topic":"Oral Anatomy & Physiology","q":["Which structure covers the root surface of a tooth?","दाँतको root surface कुन संरचनाले ढाक्छ?",["Cementum","Enamel","Pulp","Predentin"],0,"Cementum covers the root dentin and provides attachment for periodontal ligament fibres.","Cementum ले root dentin ढाक्छ र periodontal ligament fibre जोडिन आधार दिन्छ।"]},{"topic":"Oral Anatomy & Physiology","q":["Which muscle is a major elevator of the mandible during chewing?","चपाउँदा mandible माथि उठाउने मुख्य muscle कुन हो?",["Masseter","Digastric","Platysma","Buccinator"],0,"The masseter is a powerful muscle of mastication that elevates the mandible.","Masseter चपाउने शक्तिशाली muscle हो र mandible माथि उठाउँछ।"]},{"topic":"Oral Anatomy & Physiology","q":["Which papillae contain taste buds on the anterior tongue?","जिब्रोको अगाडिको भागमा taste bud कुन papillae मा हुन्छन्?",["Fungiform papillae","Filiform papillae","None of the papillae","Lingual tonsils"],0,"Fungiform papillae contain taste buds; filiform papillae are primarily mechanical.","Fungiform papillae मा taste bud हुन्छन्; filiform papillae मुख्यतः mechanical कामका हुन्।"]},{"topic":"Oral Anatomy & Physiology","q":["Which nerve provides most general sensation to the anterior two-thirds of the tongue?","जिब्रोको अगाडिको दुई-तिहाइ भागमा सामान्य sensation कुन nerve ले दिन्छ?",["Lingual nerve","Hypoglossal nerve","Glossopharyngeal nerve","Facial nerve motor branch"],0,"The lingual nerve, a branch of V3, carries general sensation from the anterior two-thirds of the tongue.","Lingual nerve (V3 को branch) ले जिब्रोको अगाडिको दुई-तिहाइ भागको सामान्य sensation बोक्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["Which condition is characterized by fungal overgrowth commonly involving Candida species?","Candida species को वृद्धि भएर हुने अवस्था कुन हो?",["Oral candidiasis","Angular fracture","Dental fluorosis","Pericoronitis only"],0,"Oral candidiasis is a fungal infection often associated with Candida overgrowth.","Oral candidiasis Candida को अत्यधिक वृद्धिसँग सम्बन्धित fungal infection हो।"]},{"topic":"Oral Pathology & Microbiology","q":["Which lesion is commonly associated with recurrent episodes of small painful ulcers?","सानो र दुख्ने ulcer पटक-पटक आउने अवस्थालाई के भनिन्छ?",["Recurrent aphthous stomatitis","Leukoplakia","Mucocele","Torus palatinus"],0,"Recurrent aphthous stomatitis presents as recurrent painful ulcers on oral mucosa.","Recurrent aphthous stomatitis मा मुखको mucosa मा पटक-पटक दुख्ने ulcer आउँछ।"]},{"topic":"Oral Pathology & Microbiology","q":["What is the term for inflammation of the dental pulp?","Dental pulp को inflammation लाई के भनिन्छ?",["Pulpitis","Periodontitis","Pericoronitis","Stomatitis"],0,"Pulpitis is inflammation of the dental pulp and may be reversible or irreversible.","Pulpitis भनेको dental pulp को inflammation हो; reversible वा irreversible हुन सक्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["Which type of microorganism causes tuberculosis?","Tuberculosis कुन प्रकारको microorganism ले गराउँछ?",["Bacterium","Virus","Fungus","Protozoan"],0,"Tuberculosis is caused by the bacterium Mycobacterium tuberculosis.","Tuberculosis Mycobacterium tuberculosis नामक bacterium ले गराउँछ।"]},{"topic":"Oral Pathology & Microbiology","q":["A fluctuant localized swelling with pus near a tooth may indicate:","दाँत नजिक pus भएको fluctuant सुन्निएको भागले के जनाउन सक्छ?",["Abscess","Aphthous ulcer","Fluorosis","Attrition"],0,"A localized collection of pus with swelling is consistent with an abscess and requires assessment.","Pus जम्मा भएर स्थानीय सुन्निएको अवस्था abscess सँग मिल्छ र जाँच आवश्यक हुन्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["What does the term adverse drug reaction mean?","Adverse drug reaction भन्नाले के बुझिन्छ?",["A harmful unintended response to a medicine used at normal doses","A desired therapeutic effect","A medicine's brand name","A method of sterilization"],0,"An adverse drug reaction is a harmful and unintended response occurring at normal medicine use.","सामान्य dose मा औषधि प्रयोग गर्दा हुने हानिकारक र अनपेक्षित प्रतिक्रिया adverse drug reaction हो।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Which information is essential when documenting a drug allergy?","Drug allergy record गर्दा कुन जानकारी आवश्यक हुन्छ?",["Suspected drug and nature of reaction","Only tablet colour","Only pharmacy name","Patient's shoe size"],0,"Document the suspected medicine, reaction, timing and severity where known.","सम्भव भएसम्म औषधिको नाम, reaction को प्रकार, समय र गम्भीरता लेख्नुपर्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Which route places a medicine under the tongue for absorption?","औषधि जिब्रोमुनि राखेर absorption गराउने route कुन हो?",["Sublingual","Intramuscular","Intradermal","Rectal"],0,"Sublingual administration allows absorption through the mucosa beneath the tongue.","Sublingual route मा जिब्रोमुनिको mucosa बाट औषधि absorb हुन्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["What is the purpose of checking the expiry date of a medicine?","औषधिको expiry date जाँच्नुको उद्देश्य के हो?",["Avoid use beyond its approved shelf life","Confirm its colour","Determine patient age","Measure blood pressure"],0,"Expiry checking helps prevent use of medicines beyond the manufacturer's supported shelf life.","Expiry date जाँच्दा manufacturer ले तोकेको अवधि नाघेको औषधि प्रयोग हुनबाट बचिन्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Which term describes the amount of medicine given at one time?","एक पटकमा दिइने औषधिको मात्रालाई के भनिन्छ?",["Dose","Half-life","Indication","Contraindication"],0,"A dose is the quantity of medicine administered at a particular time.","Dose भनेको एक पटकमा दिइने औषधिको मात्रा हो।"]},{"topic":"Basic Periodontology I","q":["Which clinical feature is commonly associated with healthy gingiva?","स्वस्थ gingiva को सामान्य विशेषता कुन हो?",["Firm consistency and absence of spontaneous bleeding","Marked swelling and suppuration","Persistent spontaneous bleeding","Progressive attachment loss"],0,"Healthy gingiva is generally firm and does not show spontaneous bleeding or suppuration.","स्वस्थ gingiva सामान्यतया कडा हुन्छ र आफैं रगत आउने वा pus हुने हुँदैन।"]},{"topic":"Basic Periodontology I","q":["What is the main purpose of interdental cleaning?","दाँतको बीच सफा गर्नुको मुख्य उद्देश्य के हो?",["Remove plaque from proximal surfaces","Whiten the tongue","Increase calculus formation","Replace toothbrushing completely"],0,"Interdental brushes or floss help disrupt plaque where a toothbrush may not reach effectively.","Interdental brush वा floss ले toothbrush नपुग्ने दाँतको बीचको plaque हटाउन मद्दत गर्छ।"]},{"topic":"Basic Periodontology I","q":["Which instrument is designed with a rounded toe and back for subgingival adaptation?","Subgingival adaptation का लागि rounded toe र back भएको instrument कुन हो?",["Universal or area-specific curette","Sickle scaler","Straight chisel","Enamel hatchet"],0,"Curettes have rounded toes and backs to support safer adaptation on root surfaces.","Curette को toe र back गोलो हुने भएकाले root surface मा सुरक्षित adaptation गर्न मद्दत गर्छ।"]},{"topic":"Basic Periodontology I","q":["What does plaque control aim to reduce?","Plaque control ले के घटाउने लक्ष्य राख्छ?",["Dental biofilm accumulation","Salivary flow to zero","Enamel thickness","Normal oral flora completely"],0,"Plaque control reduces harmful biofilm accumulation and helps prevent gingival inflammation and caries.","Plaque control ले हानिकारक biofilm घटाई gingival inflammation र caries रोक्न मद्दत गर्छ।"]},{"topic":"Basic Periodontology I","q":["Which factor is important when teaching brushing to a patient with limited dexterity?","हातको सीप कम भएको बिरामीलाई brushing सिकाउँदा कुन कुरा महत्त्वपूर्ण हुन्छ?",["Adapt the handle and technique to the patient's ability","Recommend vigorous scrubbing","Avoid all aids","Use the smallest brush regardless of need"],0,"Modified handles, powered brushes or caregiver assistance may improve effective plaque removal.","Handle परिवर्तन, powered brush वा caregiver सहयोगले plaque हटाउन सजिलो बनाउन सक्छ।"]},{"topic":"Basic Periodontology II","q":["What is furcation involvement?","Furcation involvement भन्नाले के बुझिन्छ?",["Loss of periodontal support in the area between roots of a multirooted tooth","Caries on an incisal edge","Pulp exposure in a single-rooted tooth","Enamel hypoplasia"],0,"Furcation involvement describes periodontal destruction extending into the root division area.","Furcation involvement भनेको धेरै root भएको दाँतको root छुट्टिने क्षेत्रमा periodontal support नष्ट हुनु हो।"]},{"topic":"Basic Periodontology II","q":["Which measurement is used to assess tooth mobility clinically?","दाँतको mobility clinical रूपमा जाँच्न के प्रयोग गरिन्छ?",["Controlled movement using instrument handles or fingers","Only visual inspection from a distance","Measuring crown colour","Pulp testing alone"],0,"Mobility is assessed by applying controlled forces and recording the degree using a recognized grading system.","नियन्त्रित बल लगाएर मान्य grading system अनुसार दाँतको mobility जाँचिन्छ।"]},{"topic":"Basic Periodontology II","q":["What is a common objective of periodontal surgery?","Periodontal surgery को सामान्य उद्देश्य के हो?",["Improve access, eliminate or reduce pockets, and support maintainability","Change tooth colour","Increase plaque retention","Replace oral hygiene instruction"],0,"Surgical approaches may improve access and periodontal tissue conditions when indicated.","आवश्यक अवस्थामा surgery ले access सुधार्ने र pocket घटाउने वा व्यवस्थापन गर्न मद्दत गर्छ।"]},{"topic":"Basic Periodontology II","q":["Which finding may indicate progression of periodontal destruction?","Periodontal destruction बढेको संकेत कुन हुन सक्छ?",["Increasing clinical attachment loss over time","Stable probing measurements","Reduced bleeding with stable tissues","No change in radiographs or clinical findings"],0,"Progressive attachment loss documented over time indicates worsening periodontal support.","समयसँगै clinical attachment loss बढ्नु periodontal support बिग्रिएको संकेत हो।"]},{"topic":"Basic Periodontology II","q":["Why is risk-based recall interval used in periodontal maintenance?","Periodontal maintenance मा risk अनुसार recall interval किन निर्धारण गरिन्छ?",["To match follow-up frequency to disease risk and stability","To schedule every patient identically","To avoid reassessment","To guarantee no recurrence"],0,"Recall intervals are individualized according to risk factors, disease history and current periodontal stability.","Risk factor, रोगको इतिहास र हालको periodontal स्थिरताअनुसार recall समय निर्धारण गरिन्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Which property describes a material's ability to return to its original shape after deformation?","Deformation पछि आफ्नो पुरानो आकारमा फर्किने गुणलाई के भनिन्छ?",["Elasticity","Solubility","Opacity","Thermal conductivity"],0,"Elasticity is the ability to recover shape after removal of the deforming force within the elastic range.","Elasticity भनेको बल हटेपछि elastic सीमा भित्र पुरानो आकारमा फर्किने गुण हो।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Why is moisture control important during many restorative procedures?","धेरै restorative procedure मा moisture control किन आवश्यक हुन्छ?",["It supports bonding and reduces contamination","It increases saliva contamination","It replaces etching","It prevents the need for isolation"],0,"Moisture control helps maintain a suitable field for bonding and placement of restorative materials.","Moisture control ले bonding र restorative material राख्न उपयुक्त क्षेत्र कायम गर्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Which instrument is commonly used to smooth and shape a restoration?","Restoration चिल्लो र आकार दिन कुन instrument प्रयोग हुन्छ?",["Finishing and polishing instruments","Periodontal probe","Aspirating syringe","Radiographic holder"],0,"Finishing burs, discs and polishing points are selected to refine restorative surfaces.","Finishing bur, disc र polishing point ले restoration को सतह मिलाउँछन्।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["What is the purpose of high-volume evacuation?","High-volume evacuation को उद्देश्य के हो?",["Remove large volumes of spray, fluid and debris near the operating field","Deliver local anaesthetic","Measure tooth shade","Cure composite resin"],0,"High-volume evacuation reduces pooled fluids and aerosols near the treatment field when used correctly.","High-volume evacuation ले उपचार क्षेत्र वरिपरि तरल र aerosol घटाउन मद्दत गर्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Which document provides the manufacturer's safe handling instructions for a dental chemical?","Dental chemical को सुरक्षित प्रयोगसम्बन्धी manufacturer निर्देशन कुन document मा हुन्छ?",["Safety Data Sheet","Appointment book","Patient consent form","Laboratory prescription only"],0,"The Safety Data Sheet provides hazard, handling, storage and emergency information for chemicals.","Safety Data Sheet मा chemical को hazard, handling, storage र emergency जानकारी हुन्छ।"]},{"topic":"Dental Radiography & Photography","q":["What is the main reason to use rectangular collimation when appropriate?","उपयुक्त अवस्थामा rectangular collimation प्रयोग गर्नुको मुख्य कारण के हो?",["Reduce the x-ray beam area and patient exposure","Increase scatter radiation","Make the receptor larger","Eliminate positioning errors"],0,"Rectangular collimation limits the beam to the receptor area and can reduce patient dose.","Rectangular collimation ले beam लाई receptor क्षेत्रमा सीमित गरी बिरामीको dose घटाउन सक्छ।"]},{"topic":"Dental Radiography & Photography","q":["Which structure should be clearly visible when assessing an adequate periapical image?","उपयुक्त periapical image मा कुन संरचना स्पष्ट देखिनुपर्छ?",["Entire tooth including root apex and surrounding periapical area","Only the incisal edge","Only the crown surface","Only the opposing arch"],0,"A diagnostic periapical image should include the whole tooth and surrounding periapical tissues.","Diagnostic periapical image मा पूरै दाँत र वरिपरिको periapical tissue देखिनुपर्छ।"]},{"topic":"Dental Radiography & Photography","q":["What is the effect of patient movement during exposure?","Exposure को समयमा बिरामी चलेमा के असर पर्न सक्छ?",["Image blur","Improved sharpness","Reduced magnification to zero","Automatic correction of angulation"],0,"Movement during exposure can cause motion blur and reduce diagnostic quality.","Exposure हुँदा movement भए image blur भएर diagnostic quality घट्न सक्छ।"]},{"topic":"Dental Radiography & Photography","q":["Which principle requires exposure to be kept as low as reasonably achievable?","Radiation exposure सम्भव भएसम्म न्यून राख्ने सिद्धान्त कुन हो?",["ALARA","Asepsis","RACE","Hawthorne principle"],0,"ALARA means keeping radiation exposure as low as reasonably achievable while obtaining diagnostic information.","ALARA ले diagnostic जानकारी पाउन आवश्यक हुने तर सम्भव भएसम्म कम radiation प्रयोग गर्न भन्छ।"]},{"topic":"Dental Radiography & Photography","q":["Why should the image receptor be positioned carefully?","Image receptor सावधानीपूर्वक position गर्नु किन आवश्यक छ?",["To reduce positioning errors and obtain diagnostic coverage","To increase patient movement","To remove the need for exposure settings","To sterilize the x-ray tube"],0,"Correct receptor positioning helps capture the required anatomy and reduces retakes.","सही receptor positioning ले आवश्यक anatomy देखाउँछ र दोहोर्‍याएर exposure दिनुपर्ने सम्भावना घटाउँछ।"]},{"topic":"Basic Medical Procedure & First Aid","q":["Which action is appropriate if a patient develops signs of hypoglycaemia but is conscious and able to swallow?","बिरामीलाई hypoglycaemia का लक्षण छन् तर होसमा छ र निल्न सक्छ भने के गर्नु उपयुक्त हुन्छ?",["Give fast-acting oral glucose according to protocol and monitor","Give nothing and continue treatment","Force the patient to exercise","Give oral glucose to an unconscious patient"],0,"A conscious patient able to swallow may receive fast-acting oral glucose under the emergency protocol.","होसमा रहेको र निल्न सक्ने बिरामीलाई protocol अनुसार छिटो असर गर्ने oral glucose दिन सकिन्छ।"]},{"topic":"Basic Medical Procedure & First Aid","q":["What should be done if a patient becomes unconscious and is not breathing normally?","बिरामी बेहोस भयो र सामान्य रूपमा सास फेरिरहेको छैन भने के गर्नुपर्छ?",["Activate emergency response and begin CPR/AED steps per training","Offer water","Wait several minutes","Place instruments in the mouth"],0,"Activate emergency medical services, start CPR and use an AED as soon as available according to training.","Emergency service बोलाई CPR सुरु गर्ने र उपलब्ध भए AED तालिमअनुसार प्रयोग गर्ने।"]},{"topic":"Basic Medical Procedure & First Aid","q":["Which measurement is obtained using a sphygmomanometer?","Sphygmomanometer ले के मापन गर्छ?",["Blood pressure","Pulse oximetry","Body temperature","Blood glucose"],0,"A sphygmomanometer is used to measure arterial blood pressure.","Sphygmomanometer ले arterial blood pressure मापन गर्छ।"]},{"topic":"Basic Medical Procedure & First Aid","q":["What is the correct response to a suspected severe allergic reaction with breathing difficulty?","सास फेर्न गाह्रो हुने गम्भीर allergic reaction शंका भए के गर्नुपर्छ?",["Activate emergency help and follow anaphylaxis protocol, including prescribed adrenaline where authorized","Ask the patient to walk","Give food and wait","Continue dental procedure"],0,"Suspected anaphylaxis is an emergency; activate help and follow the established protocol promptly.","Anaphylaxis emergency हो; तुरुन्त सहयोग बोलाई स्थापित protocol अनुसार कार्य गर्नुपर्छ।"]},{"topic":"Basic Medical Procedure & First Aid","q":["Why should medical history be updated at each relevant visit?","आवश्यक प्रत्येक visit मा medical history किन update गर्नुपर्छ?",["Health status and medicines may have changed","It is only an administrative formality","It replaces clinical examination","It is needed only for children"],0,"Changes in disease, medicines, allergies and recent treatment can alter dental care and emergency risk.","रोग, औषधि, allergy र हालैको उपचार परिवर्तनले dental care र emergency risk बदल्न सक्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["What is secondary prevention in oral health?","मुख स्वास्थ्यमा secondary prevention भन्नाले के बुझिन्छ?",["Early detection and prompt treatment of disease","Preventing exposure before disease begins only","Rehabilitation after disability only","Avoiding screening"],0,"Secondary prevention emphasizes screening, early diagnosis and timely treatment.","Secondary prevention ले screening, चाँडो diagnosis र समयमै उपचारमा जोड दिन्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["Which index is commonly used to record oral hygiene status using debris and calculus scores?","Debris र calculus score प्रयोग गरी oral hygiene status लेख्न कुन index प्रयोग हुन्छ?",["Simplified Oral Hygiene Index (OHI-S)","DMFT only","Dean's fluorosis index","Community Periodontal Index only"],0,"OHI-S assesses debris and calculus on selected tooth surfaces.","OHI-S ले छानिएका दाँतका सतहमा debris र calculus को अवस्था मूल्याङ्कन गर्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["What is the purpose of a referral pathway in a community oral-health programme?","Community oral-health programme मा referral pathway को उद्देश्य के हो?",["Connect people needing care with appropriate services","Replace diagnosis","Avoid follow-up","Limit access to care"],0,"Referral pathways ensure that people with identified needs can access suitable assessment and treatment.","Referral pathway ले समस्या पहिचान भएका व्यक्तिलाई उपयुक्त जाँच र उपचार सेवासँग जोड्छ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["Which group may need additional support to access oral-health services?","मुख स्वास्थ्य सेवा लिन थप सहयोग आवश्यक पर्न सक्ने समूह कुन हो?",["People with disabilities or mobility barriers","Only people with no dental disease","Only dental professionals","Only people living near hospitals"],0,"Equity-focused programmes identify access barriers and adapt services for underserved groups.","समतामूलक कार्यक्रमले पहुँचका अवरोध पहिचान गरी सेवा आवश्यकताअनुसार मिलाउँछ।"]},{"topic":"Dental Public Health & Community Dentistry","q":["What is the purpose of surveillance in public health?","Public health मा surveillance को उद्देश्य के हो?",["Systematic ongoing collection and use of health data","One-time collection without analysis","Individual treatment only","Advertising health products"],0,"Surveillance continuously collects, analyzes and interprets health data to guide action.","Surveillance ले स्वास्थ्य तथ्याङ्क निरन्तर संकलन, विश्लेषण र प्रयोग गरी निर्णयमा सहयोग गर्छ।"]},{"topic":"Health Education","q":["Which approach best supports adult learning during oral-health education?","मुख स्वास्थ्य शिक्षामा adult learning लाई कुन approach ले राम्रो सहयोग गर्छ?",["Relate content to learners' experience and practical needs","Use unexplained technical terms only","Avoid questions","Provide information unrelated to daily life"],0,"Adult learning is strengthened when education is relevant, participatory and linked to real-life needs.","Adult learning प्रभावकारी बनाउन शिक्षा सान्दर्भिक, सहभागितामूलक र दैनिक जीवनसँग जोडिएको हुनुपर्छ।"]},{"topic":"Health Education","q":["What is a measurable learning objective?","मापन गर्न सकिने learning objective को उदाहरण कुन हो?",["Learner will demonstrate the correct brushing sequence","Learner will understand everything","Learner will like the session","Learner will become perfect"],0,"A measurable objective describes an observable action or outcome that can be assessed.","मापनयोग्य objective ले देख्न र मूल्याङ्कन गर्न सकिने व्यवहार वा नतिजा बताउँछ।"]},{"topic":"Health Education","q":["Which tool can be used to evaluate whether a patient understood brushing instruction?","बिरामीले brushing instruction बुझेको छ कि छैन जाँच्न कुन विधि प्रयोग गर्न सकिन्छ?",["Ask the patient to demonstrate the technique","Assume understanding from a nod","End the session immediately","Check the patient's age only"],0,"Teach-back or return demonstration helps confirm understanding and skill.","Teach-back वा return demonstration ले बुझाइ र सीप पुष्टि गर्छ।"]},{"topic":"Health Education","q":["Which communication behaviour supports effective patient education?","प्रभावकारी patient education का लागि कुन communication व्यवहार उपयोगी हुन्छ?",["Use clear language and invite questions","Interrupt frequently","Use blame and shame","Give several instructions at once without checking"],0,"Clear, respectful communication with opportunities for questions improves understanding.","स्पष्ट र सम्मानजनक संवाद तथा प्रश्न सोध्ने अवसरले बुझाइ बढाउँछ।"]},{"topic":"Health Education","q":["Why should health messages be culturally and linguistically appropriate?","स्वास्थ्य सन्देश सांस्कृतिक र भाषिक रूपमा उपयुक्त हुनु किन आवश्यक छ?",["To improve relevance, understanding and acceptance","To make messages longer","To avoid community feedback","To use technical words only"],0,"Messages that fit the audience's language and context are more likely to be understood and adopted.","श्रोताको भाषा र परिवेशअनुसार सन्देश भए बुझ्न र अपनाउन सजिलो हुन्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["A cross-sectional study primarily measures:","Cross-sectional study ले मुख्यतः के मापन गर्छ?",["Exposure and outcome at a particular point or period","Only future incidence","Treatment efficacy in a randomized trial","Disease progression in every individual"],0,"Cross-sectional studies assess a population at a defined time and are commonly used to estimate prevalence.","Cross-sectional study ले निश्चित समयमा जनसंख्याको अवस्था हेर्छ र prevalence मापनमा उपयोगी हुन्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["What is the main feature of a randomized controlled trial?","Randomized controlled trial को मुख्य विशेषता के हो?",["Participants are allocated to groups by random assignment","All participants receive the same intervention","There is no comparison group","Only past records are reviewed"],0,"Random allocation helps balance known and unknown confounders between study groups.","Random allocation ले study group बीच थाहा भएका र नभएका confounder सन्तुलित गर्न मद्दत गर्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["What does a risk factor indicate?","Risk factor ले के जनाउँछ?",["An attribute associated with an increased likelihood of an outcome","A guaranteed cause in every person","A treatment outcome","A laboratory instrument"],0,"A risk factor is associated with a higher probability of an outcome but does not guarantee it.","Risk factor ले नतिजा हुने सम्भावना बढेको जनाउँछ, तर सबैमा रोग हुन्छ भन्ने होइन।"]},{"topic":"Epidemiology & Community Diagnosis","q":["Why is sampling used in community surveys?","Community survey मा sampling किन प्रयोग गरिन्छ?",["To study a selected subset when examining everyone is impractical","To avoid defining a population","To guarantee no bias","To remove the need for data analysis"],0,"Sampling allows estimates about a population from a selected group when designed appropriately.","उचित sampling बाट छानिएको समूहको तथ्याङ्क प्रयोग गरी ठूलो जनसंख्याबारे अनुमान गर्न सकिन्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["What is a confounding variable?","Confounding variable भन्नाले के बुझिन्छ?",["A factor associated with both exposure and outcome that can distort an observed association","The main study result","A type of questionnaire","A random error-free measurement"],0,"A confounder can distort the apparent relationship between an exposure and an outcome.","Confounder ले exposure र outcome बीचको देखिएको सम्बन्धलाई गलत रूपमा प्रभावित गर्न सक्छ।"]},{"topic":"Office Health Management","q":["What is the purpose of an appointment register?","Appointment register को उद्देश्य के हो?",["Organize patient visits and clinic workflow","Record sterilizer temperature only","Replace clinical notes","Record staff salaries only"],0,"Appointment systems help coordinate patient flow, resources and continuity of care.","Appointment system ले बिरामीको आवागमन, स्रोत र उपचारको निरन्तरता मिलाउँछ।"]},{"topic":"Office Health Management","q":["Which practice supports confidentiality of electronic patient records?","Electronic patient record को confidentiality कायम राख्न कुन अभ्यास उपयोगी हुन्छ?",["Use access controls and secure authentication","Share one password publicly","Leave records open on shared screens","Send records to unrelated people"],0,"Role-based access, strong authentication and secure handling protect patient information.","Role-based access, बलियो authentication र सुरक्षित व्यवस्थापनले बिरामीको जानकारी जोगाउँछ।"]},{"topic":"Office Health Management","q":["Why is equipment maintenance documentation important?","Equipment maintenance documentation किन महत्त्वपूर्ण हुन्छ?",["It supports safety, reliability and traceability","It replaces equipment testing","It proves every treatment was successful","It removes the need for staff training"],0,"Maintenance records show checks, repairs and servicing that support safe equipment use.","Maintenance record ले जाँच, मर्मत र servicing को विवरण राखेर सुरक्षित प्रयोगमा सहयोग गर्छ।"]},{"topic":"Office Health Management","q":["What should be done when a clinical incident occurs?","Clinical incident हुँदा के गर्नुपर्छ?",["Provide immediate care, report and document according to policy","Hide the incident","Alter the patient's record","Discuss identifiable details publicly"],0,"Incident management prioritizes patient safety, timely reporting, accurate documentation and learning.","Incident management मा बिरामीको सुरक्षा, समयमै report, सही documentation र सुधारलाई प्राथमिकता दिइन्छ।"]},{"topic":"Office Health Management","q":["What is stock rotation using FEFO?","FEFO अनुसार stock rotation भन्नाले के बुझिन्छ?",["First Expiry, First Out","First Entry, First Open","Final Entry, Final Order","Fast Equipment, Fast Operation"],0,"FEFO means items with the earliest expiry date are used or issued first.","FEFO मा पहिले expiry हुने सामग्री पहिले प्रयोग वा वितरण गरिन्छ।"]},{"topic":"Environmental Health","q":["Which method is important for preventing contamination of drinking water?","पिउने पानी दूषित हुनबाट रोक्न कुन विधि महत्त्वपूर्ण हुन्छ?",["Protect sources and use appropriate treatment and safe storage","Store water in uncovered dirty containers","Mix wastewater with drinking water","Ignore water quality testing"],0,"Safe water requires source protection, appropriate treatment and hygienic storage.","सुरक्षित पानीका लागि स्रोत संरक्षण, उचित उपचार र सफा भण्डारण आवश्यक हुन्छ।"]},{"topic":"Environmental Health","q":["What is the main purpose of ventilation in a clinical room?","Clinical room मा ventilation को मुख्य उद्देश्य के हो?",["Support indoor air quality and reduce accumulation of airborne contaminants","Increase dust accumulation","Replace surface cleaning","Sterilize instruments"],0,"Adequate ventilation helps maintain indoor air quality and manage airborne contaminants.","पर्याप्त ventilation ले भित्री हावाको गुणस्तर कायम राखी हावामा रहेका दूषित कण घटाउन मद्दत गर्छ।"]},{"topic":"Environmental Health","q":["Which practice reduces mosquito breeding around a health facility?","स्वास्थ्य संस्थाको वरिपरि लामखुट्टे बढ्न नदिन कुन अभ्यास उपयोगी हुन्छ?",["Remove stagnant water from containers and drains","Keep uncovered water pools","Store waste in open areas","Block all drainage"],0,"Removing stagnant water eliminates common mosquito breeding sites.","जमेको पानी हटाउँदा लामखुट्टेको प्रजननस्थल हट्छ।"]},{"topic":"Environmental Health","q":["Why should clinical surfaces be cleaned before disinfection when visibly soiled?","देखिने फोहोर भएको clinical surface लाई disinfection अघि सफा किन गर्नुपर्छ?",["Organic material can interfere with disinfectant action","Cleaning makes disinfectant unnecessary in all cases","Dirt improves disinfection","It increases microbial growth"],0,"Cleaning removes soil and organic material that can reduce the effectiveness of disinfectants.","Cleaning ले disinfectant को प्रभाव घटाउन सक्ने फोहोर र organic material हटाउँछ।"]},{"topic":"Environmental Health","q":["Which waste category commonly includes blood-soaked gauze from clinical care?","Clinical care मा रगतले भिजेको gauze सामान्यतया कुन waste category मा पर्छ?",["Infectious or contaminated healthcare waste according to local policy","General recyclable paper","Food waste","Uncontaminated packaging"],0,"Blood-contaminated materials should be segregated and managed under applicable healthcare-waste rules.","रगत लागेको सामग्रीलाई स्थानीय healthcare-waste नियमअनुसार छुट्याएर व्यवस्थापन गर्नुपर्छ।"]},{"topic":"Food & Nutrition","q":["Which nutrient is the body's main source of readily available energy?","शरीरलाई छिटो उपलब्ध हुने ऊर्जाको मुख्य स्रोत कुन nutrient हो?",["Carbohydrate","Vitamin C","Calcium","Water"],0,"Carbohydrates are a major source of readily available energy.","Carbohydrate शरीरलाई सजिलै उपलब्ध हुने ऊर्जाको प्रमुख स्रोत हो।"]},{"topic":"Food & Nutrition","q":["Which mineral is important for tooth and bone mineralization?","दाँत र हड्डीको mineralization का लागि कुन mineral महत्त्वपूर्ण हुन्छ?",["Calcium","Iron only","Sodium","Iodine"],0,"Calcium is a major mineral component of bones and teeth.","Calcium हड्डी र दाँतको प्रमुख mineral घटक हो।"]},{"topic":"Food & Nutrition","q":["Frequent intake of fermentable sugars increases caries risk mainly by:","पटक-पटक fermentable sugar खाँदा caries risk मुख्यतः किन बढ्छ?",["Providing substrate for acid production by plaque bacteria","Increasing enamel thickness","Stopping bacterial metabolism","Increasing salivary buffering permanently"],0,"Plaque bacteria ferment sugars to acids, causing repeated low-pH episodes and mineral loss.","Plaque bacteria ले sugar बाट acid बनाउँछन्, pH घट्छ र दाँतको mineral हराउँछ।"]},{"topic":"Food & Nutrition","q":["Which dietary advice is generally helpful for reducing caries risk?","Caries risk घटाउन सामान्यतया कुन dietary advice उपयोगी हुन्छ?",["Reduce frequency of sugary snacks and drinks","Sip sweet drinks throughout the day","Use sticky sweets between meals frequently","Replace water with soft drinks"],0,"Reducing the frequency of free-sugar exposure decreases repeated acid challenges to teeth.","Free sugar पटक-पटक खाने बानी घटाउँदा दाँतमा बारम्बार acid attack कम हुन्छ।"]},{"topic":"Food & Nutrition","q":["Which vitamin helps calcium absorption and bone health?","Calcium absorption र bone health मा कुन vitamin ले मद्दत गर्छ?",["Vitamin D","Vitamin K only","Vitamin B12","Vitamin C only"],0,"Vitamin D supports intestinal calcium absorption and normal bone mineralization.","Vitamin D ले आन्द्राबाट calcium absorb हुन र हड्डीको सामान्य mineralization मा सहयोग गर्छ।"]}];
 const thirdExpandedBank=[{"topic":"Human Anatomy & Physiology","q":["Which gland secretes insulin?","Insulin कुन ग्रन्थीले स्राव गर्छ?",["Pancreas","Thyroid","Pituitary","Adrenal"],0,"Beta cells in the pancreatic islets secrete insulin.","Pancreas को islets का beta cells ले insulin स्राव गर्छन्।"]},{"topic":"Oral Anatomy & Physiology","q":["Which nerve provides general sensation to the anterior two-thirds of the tongue?","जिब्रोको अगाडिको दुई तिहाइ भागमा सामान्य संवेदना कुन nerve ले दिन्छ?",["Lingual nerve","Glossopharyngeal nerve","Hypoglossal nerve","Vagus nerve"],0,"The lingual nerve, a branch of V3, carries general sensation from the anterior two-thirds.","V3 को शाखा lingual nerve ले जिब्रोको अगाडिको दुई तिहाइको सामान्य संवेदना बोक्छ।"]},{"topic":"Oral Pathology & Microbiology","q":["Which condition is characterised by white curd-like plaques that may wipe off?","पुछ्दा हट्न सक्ने सेतो दहीजस्तो plaque कुन अवस्थाको लक्षण हो?",["Pseudomembranous candidiasis","Leukoplakia","Lichen planus","Fordyce granules"],0,"Pseudomembranous candidiasis often presents as wipeable white plaques.","Pseudomembranous candidiasis मा पुछ्दा हट्न सक्ने सेतो plaque देखिन सक्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["Which medication group reduces fever?","ज्वरो घटाउने औषधि समूह कुन हो?",["Antipyretics","Anticoagulants","Antifungals","Antacids"],0,"Antipyretics such as paracetamol reduce fever.","Paracetamol जस्ता antipyretics ले ज्वरो घटाउँछन्।"]},{"topic":"Basic Periodontology I","q":["What is the usual endpoint when using a periodontal probe?","Periodontal probe प्रयोग गर्दा सामान्यतया कुन स्थानसम्म मापन गरिन्छ?",["Base of the gingival sulcus or periodontal pocket","Crown incisal edge","Root apex","Pulp chamber"],0,"The probe is gently advanced to the base of the sulcus or pocket.","Probe बिस्तारै sulcus वा pocket को आधारसम्म पुर्‍याइन्छ।"]},{"topic":"Basic Periodontology II","q":["Which condition is associated with loss of alveolar bone support?","Alveolar bone support हराउँदै जाने अवस्था कुन हो?",["Periodontitis","Reversible pulpitis","Enamel fluorosis","Dentin hypersensitivity"],0,"Periodontitis involves destruction of tooth-supporting tissues, including alveolar bone.","Periodontitis मा alveolar bone लगायत दाँतलाई सहारा दिने tissue नष्ट हुन्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["What is the main role of a dental curing light?","Dental curing light को मुख्य काम के हो?",["Polymerise light-activated restorative resin","Sterilise hand instruments","Remove calculus","Measure shade"],0,"Curing lights activate photoinitiators to polymerise resin-based materials.","Curing light ले photoinitiator सक्रिय गरी resin-based material polymerise गर्छ।"]},{"topic":"Dental Radiography & Photography","q":["What does a bitewing radiograph show particularly well?","Bitewing radiograph ले कुन कुरा विशेष रूपमा राम्रो देखाउँछ?",["Interproximal crowns and crestal bone levels","Entire root apices of all teeth","TMJ disc position","Maxillary sinus in full"],0,"Bitewings are useful for detecting interproximal caries and assessing crestal bone.","Bitewing interproximal caries पत्ता लगाउन र crestal bone हेर्न उपयोगी हुन्छ।"]},{"topic":"Basic Medical Procedure & First Aid","q":["What is the first-line action for a conscious adult with choking who cannot speak or cough effectively?","बोल्न वा प्रभावकारी रूपमा खोक्न नसक्ने, घाँटीमा अड्किएको होसमा रहेको वयस्कलाई पहिलो सहायता के हो?",["Give appropriate back blows and abdominal thrusts per current protocol","Offer water","Perform blind finger sweep","Lay flat and leave alone"],0,"Follow the current choking first-aid sequence and activate emergency help.","हालको choking first-aid क्रमअनुसार back blows र abdominal thrusts दिनुहोस् र emergency सहयोग बोलाउनुहोस्।"]},{"topic":"Dental Public Health & Community Dentistry","q":["What is herd protection in a vaccination programme?","खोप कार्यक्रममा herd protection भनेको के हो?",["Reduced transmission when enough people are immune","Protection only for one vaccinated person","Treatment of active dental caries","A type of dental filling"],0,"High population immunity can reduce spread and indirectly protect susceptible people.","जनसंख्यामा पर्याप्त immunity हुँदा संक्रमण फैलावट घटेर संवेदनशील व्यक्तिलाई पनि अप्रत्यक्ष सुरक्षा मिल्छ।"]},{"topic":"Health Education","q":["Which objective is most measurable?","कुन objective सबैभन्दा मापनयोग्य छ?",["By the end, learners will demonstrate the correct brushing technique","Learners will know everything about teeth","Oral health will improve someday","People will like the session"],0,"A demonstrable behaviour can be observed and assessed against clear criteria.","देखाउन सकिने व्यवहारलाई स्पष्ट मापदण्डका आधारमा अवलोकन र मूल्याङ्कन गर्न सकिन्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["What is a risk factor?","Risk factor भनेको के हो?",["A characteristic associated with increased probability of disease","A guaranteed cause in every person","A treatment outcome","A type of health facility"],0,"A risk factor is associated with a higher likelihood of an outcome but does not guarantee it.","Risk factor रोग हुने सम्भावना बढाउनेसँग सम्बन्धित हुन्छ, तर रोग निश्चित गराउँदैन।"]},{"topic":"Office Health Management","q":["What should be recorded after a sterilisation cycle?","Sterilisation cycle पछि के अभिलेख राख्नुपर्छ?",["Cycle details and monitoring results","Only the operator's favourite instrument","Patient's unrelated personal details","Nothing if instruments look clean"],0,"Documentation supports traceability and verification of sterilisation processes.","अभिलेखले sterilisation प्रक्रिया trace र verify गर्न मद्दत गर्छ।"]},{"topic":"Environmental Health","q":["Where should used needles be discarded?","प्रयोग भइसकेका सुई कहाँ फाल्नुपर्छ?",["Puncture-resistant sharps container","Ordinary open waste basket","Plastic drinking-water bottle","General paper bin"],0,"Sharps must be discarded immediately into an approved puncture-resistant container.","Sharps तुरुन्तै स्वीकृत puncture-resistant container मा फाल्नुपर्छ।"]},{"topic":"Food & Nutrition","q":["Which mineral is a major component of tooth enamel?","दाँतको enamel को प्रमुख mineral कुन हो?",["Calcium","Iron","Iodine","Potassium"],0,"Enamel mineral is mainly hydroxyapatite, a calcium-phosphate crystal.","Enamel मुख्यतः calcium-phosphate crystal hydroxyapatite बाट बनेको हुन्छ।"]}];
const fifthExpandedBank=[{"topic":"Human Anatomy & Physiology","q":["Which blood vessels carry blood away from the heart?","मुटुबाट रगत बाहिर लैजाने रक्तनली कुन हुन्?",["Arteries","Veins","Capillaries","Venules"],0,"Arteries carry blood away from the heart.","Arteries ले मुटुबाट रगत बाहिर लैजान्छन्।"]},{"topic":"Oral Anatomy & Physiology","q":["Which cells produce enamel during tooth development?","दाँत विकास हुँदा enamel बनाउने कोष कुन हुन्?",["Ameloblasts","Odontoblasts","Cementoblasts","Fibroblasts"],0,"Ameloblasts form enamel during odontogenesis.","Odontogenesis को क्रममा ameloblasts ले enamel बनाउँछन्।"]},{"topic":"Oral Pathology & Microbiology","q":["Which oral condition is commonly linked to iron deficiency?","Iron deficiency सँग सम्बन्धित हुन सक्ने oral अवस्था कुन हो?",["Atrophic glossitis","Dental fluorosis","Pericoronitis","Mucocele"],0,"Iron deficiency may be associated with a smooth, sore atrophic tongue.","Iron deficiency मा जिब्रो चिल्लो, दुख्ने र atrophic हुन सक्छ।"]},{"topic":"Dental Pharmacy & Pharmacology","q":["What does the abbreviation 'BD' commonly mean in prescription directions?","Prescription मा 'BD' ले सामान्यतया के जनाउँछ?",["Twice daily","Once daily","Three times daily","At bedtime only"],0,"BD commonly indicates twice daily; prescriptions should use clear, unambiguous instructions.","BD ले सामान्यतया दिनमा दुई पटक जनाउँछ; निर्देशन स्पष्ट हुनुपर्छ।"]},{"topic":"Basic Periodontology I","q":["Which device is commonly recommended to clean interdental spaces?","दाँतबीचको खाली स्थान सफा गर्न कुन साधन सिफारिस गरिन्छ?",["Interdental brush when spaces permit","Tongue scraper only","Cotton roll","Mouth mirror"],0,"Interdental brushes are useful where embrasure spaces allow appropriate sizing.","दाँतबीचको खाली ठाउँअनुसार सही size को interdental brush उपयोगी हुन्छ।"]},{"topic":"Basic Periodontology II","q":["What does a periodontal abscess commonly present with?","Periodontal abscess मा सामान्यतया के देखिन सक्छ?",["Localised swelling and pain near a periodontal pocket","Only enamel white spots","Painless tooth eruption","A normal gingival margin"],0,"A periodontal abscess may cause localised swelling, tenderness and suppuration.","Periodontal abscess मा स्थानीय सुन्निने, दुख्ने र pus आउन सक्छ।"]},{"topic":"Dental Materials, Instruments & Assisting","q":["Which instrument is used to mix dental cement on a glass slab?","Glass slab मा dental cement मिसाउन कुन instrument प्रयोग हुन्छ?",["Cement spatula","Periodontal probe","Mouth gag","Surgical suction tip"],0,"A cement spatula is used to mix many dental cements on a suitable slab or pad.","Cement spatula ले उपयुक्त slab वा pad मा धेरै प्रकारका dental cement मिसाउँछ।"]},{"topic":"Dental Radiography & Photography","q":["What is the main reason to remove removable metallic objects before an extraoral dental radiograph?","Extraoral dental radiograph अघि हटाउन मिल्ने धातुका वस्तु हटाउनुको मुख्य कारण के हो?",["Avoid artefacts that obscure anatomy","Increase patient weight","Sterilise the receptor","Reduce image resolution"],0,"Metallic objects can create artefacts and obscure diagnostic structures.","धातुका वस्तुले artefact बनाएर diagnosis का लागि चाहिने संरचना छोप्न सक्छन्।"]},{"topic":"Basic Medical Procedure & First Aid","q":["What should be done for a minor thermal burn immediately after ensuring safety?","सुरक्षा सुनिश्चित गरेपछि सामान्य thermal burn मा तत्काल के गर्नुपर्छ?",["Cool the burn under cool running water","Apply ice directly","Apply toothpaste","Break any blisters"],0,"Cool running water helps limit tissue damage; avoid ice and unproven topical substances.","चिसो बग्ने पानीले tissue damage घटाउन मद्दत गर्छ; सिधै बरफ वा अप्रमाणित पदार्थ नलगाउनुहोस्।"]},{"topic":"Dental Public Health & Community Dentistry","q":["What is the main purpose of oral health promotion?","Oral health promotion को मुख्य उद्देश्य के हो?",["Enable people to improve control over oral health","Treat only advanced disease","Replace all preventive services","Focus only on dental equipment"],0,"Health promotion builds skills and supportive environments for better oral health.","Health promotion ले सीप र सहयोगी वातावरण विकास गरी oral health सुधार्छ।"]},{"topic":"Health Education","q":["Which approach is most appropriate when educating a person with limited health literacy?","Health literacy कम भएको व्यक्तिलाई शिक्षा दिँदा कुन उपाय उपयुक्त हुन्छ?",["Use plain language, pictures and teach-back","Use complex medical terminology","Give a long leaflet only","Avoid checking understanding"],0,"Plain language and teach-back help make information accessible and confirm understanding.","सरल भाषा, चित्र र teach-back ले जानकारी बुझ्न सजिलो बनाउँछ र बुझाइ पुष्टि गर्छ।"]},{"topic":"Epidemiology & Community Diagnosis","q":["What is the main purpose of a case definition in an outbreak investigation?","Outbreak अनुसन्धानमा case definition को मुख्य उद्देश्य के हो?",["Apply consistent criteria to identify cases","Prescribe medication to everyone","Determine clinic fees","Replace laboratory testing in all cases"],0,"A standard case definition ensures cases are identified consistently for investigation.","Standard case definition ले अनुसन्धानमा केसहरू एकरूप मापदण्डबाट पहिचान गर्न मद्दत गर्छ।"]},{"topic":"Office Health Management","q":["Why should emergency contact numbers be displayed in a clinic?","क्लिनिकमा emergency contact number देखिने गरी राख्नु किन आवश्यक छ?",["Allow staff to obtain urgent assistance quickly","Improve wall decoration","Replace emergency training","Avoid documenting incidents"],0,"Visible emergency contacts support rapid communication during urgent events.","देखिने emergency contact ले आकस्मिक अवस्थामा छिटो सहयोग माग्न मद्दत गर्छ।"]},{"topic":"Environmental Health","q":["Which action is appropriate after a blood spill on a clinical surface?","Clinical surface मा रगत पोखिएपछि उपयुक्त काम कुन हो?",["Use PPE and clean/disinfect according to protocol","Wipe with bare hands","Cover it with paper and leave it","Spray perfume over it"],0,"Blood spills require appropriate PPE, cleaning and approved disinfection procedures.","रगत पोखिँदा PPE लगाई protocol अनुसार सफा र स्वीकृत disinfectant प्रयोग गर्नुपर्छ।"]},{"topic":"Food & Nutrition","q":["Which food group is a major source of dietary fibre?","Dietary fibre को प्रमुख स्रोत कुन खाद्य समूह हो?",["Whole grains, fruits and vegetables","Refined sugar","Butter and ghee","Soft drinks"],0,"Whole grains, fruits and vegetables provide dietary fibre.","Whole grains, फलफूल र तरकारी dietary fibre का स्रोत हुन्।"]}];
