 bank.push(...[{"topic":"Basic Periodontology I","q":["Which epithelial layer covers the outer surface of attached gingiva?","Attached gingiva को बाहिरी सतह कुन epithelial layer ले ढाक्छ?",["Keratinized stratified squamous epithelium","Simple columnar epithelium","Transitional epithelium","Simple cuboidal epithelium"],0,"The oral epithelium covering attached gingiva is generally keratinized or parakeratinized stratified squamous epithelium.","Attached gingiva को oral epithelium सामान्यतया keratinized वा parakeratinized stratified squamous epithelium हुन्छ।"]},{"topic":"Basic Periodontology I","q":["The gingival sulcus is the space between the tooth and the:","Gingival sulcus दाँत र कुन भागबीचको space हो?",["Free gingiva","Attached gingiva","Alveolar mucosa","Periodontal ligament"],0,"The gingival sulcus is the shallow crevice between the tooth surface and free gingival margin.","Gingival sulcus दाँतको सतह र free gingiva को किनाराबीचको सानो खाडल हो।"]},{"topic":"Basic Periodontology I","q":["Which fibre group helps support the marginal gingiva by extending from cementum?","Cementum बाट फैलिई marginal gingiva लाई support गर्ने fibre कुन हो?",["Dentogingival fibres","Transseptal fibres only","Oblique PDL fibres","Alveolar crest fibres only"],0,"Dentogingival fibres extend from cementum into the gingiva and help support marginal gingiva.","Dentogingival fibres cementum बाट gingiva तर्फ फैलिई marginal gingiva लाई support गर्छन्।"]},{"topic":"Basic Periodontology I","q":["Gingival blood supply is derived from supraperiosteal, periodontal ligament and:","Gingiva मा supraperiosteal र periodontal ligament vessel बाहेक कुनबाट रगत पुग्छ?",["Interdental vessels","Pulpal vessels alone","Only the facial vein","Only the inferior alveolar nerve"],0,"Gingival blood supply includes supraperiosteal vessels, periodontal ligament vessels and vessels from interdental septa.","Gingiva मा supraperiosteal, periodontal ligament र interdental septa का vessel बाट रगत पुग्छ।"]},{"topic":"Basic Periodontology I","q":["The acquired pellicle is important because it:","Acquired pellicle किन महत्त्वपूर्ण हुन्छ?",["Provides a surface for early bacterial attachment","Destroys all oral bacteria","Is made only of calculus","Prevents all plaque formation"],0,"The salivary pellicle forms on cleaned enamel and provides receptors for early bacterial colonization.","सफा enamel मा saliva बाट pellicle बन्छ र प्रारम्भिक bacteria टाँसिने आधार दिन्छ।"]},{"topic":"Basic Periodontology I","q":["After acquired pellicle formation, which event generally occurs first in biofilm development?","Acquired pellicle बनेपछि biofilm विकासमा सामान्यतया पहिले के हुन्छ?",["Adhesion of early colonizing bacteria","Complete mineralization","Periodontal pocket formation","Loss of salivary proteins"],0,"Early colonizing bacteria adhere to pellicle receptors; the biofilm then develops through growth and co-aggregation.","प्रारम्भिक bacteria pellicle मा टाँसिन्छन्; त्यसपछि वृद्धि र co-aggregation हुँदै biofilm विकसित हुन्छ।"]},{"topic":"Basic Periodontology I","q":["Which statement correctly distinguishes supragingival and subgingival calculus?","Supragingival र subgingival calculus बीचको सही फरक कुन हो?",["Supragingival is above the gingival margin; subgingival is below it","Subgingival calculus is always soft","Supragingival calculus forms only in pockets","There is no anatomical distinction"],0,"The distinction is based on the gingival margin: supragingival deposits lie coronal to it and subgingival deposits apical to it.","Gingival margin को आधारमा supragingival deposit माथि र subgingival deposit तल हुन्छ।"]},{"topic":"Basic Periodontology I","q":["A major mineral component of dental calculus is:","Dental calculus को प्रमुख mineral component कुन हो?",["Calcium phosphate","Sodium chloride only","Potassium iodide","Iron oxide"],0,"Dental calculus is mineralized plaque and contains calcium phosphate mineral phases.","Dental calculus mineralized plaque हो र यसमा calcium phosphate mineral phase हुन्छ।"]},{"topic":"Basic Periodontology I","q":["The main anticaries action of fluoride toothpaste is to:","Fluoride toothpaste को मुख्य anticaries कार्य के हो?",["Promote remineralization and reduce demineralization","Dissolve all calculus","Sterilize the mouth","Permanently whiten dentin"],0,"Fluoride supports remineralization and makes enamel more resistant to acid-mediated mineral loss.","Fluoride ले remineralization बढाउँछ र acid का कारण हुने mineral loss विरुद्ध enamel लाई प्रतिरोधी बनाउँछ।"]},{"topic":"Basic Periodontology I","q":["Potassium salts in some desensitizing dentifrices are intended to:","केही desensitizing toothpaste मा potassium salt किन राखिन्छ?",["Reduce dentinal nerve excitability","Remove subgingival calculus","Increase enamel porosity","Treat periodontal abscess"],0,"Potassium salts may reduce nerve excitability and help manage dentinal hypersensitivity.","Potassium salt ले nerve excitability घटाएर dentinal hypersensitivity कम गर्न सहयोग गर्न सक्छ।"]},{"topic":"Basic Periodontology I","q":["In the Modified Bass technique, toothbrush bristles are directed approximately 45 degrees toward the:","Modified Bass technique मा bristle करिब ४५ degree मा कुनतर्फ राखिन्छ?",["Gingival sulcus","Occlusal surface only","Tongue surface","Incisal edge"],0,"Modified Bass positions bristles toward the gingival sulcus with gentle short vibratory movements.","Modified Bass मा bristle gingival sulcus तर्फ राखेर हल्का छोटो vibration गरिन्छ।"]},{"topic":"Basic Periodontology I","q":["For open interdental embrasures, which aid may be appropriate when correctly sized?","खुला interdental embrasure मा सही size छानेर कुन साधन उपयोगी हुन सक्छ?",["Interdental brush","Large hard-bristled brush only","Forceful wooden toothpick","No interdental cleaning"],0,"An appropriately sized interdental brush cleans open embrasures without forcing or traumatizing tissues.","उचित size को interdental brush ले tissue मा चोट नपुर्‍याई खुला interdental space सफा गर्छ।"]},{"topic":"Basic Periodontology I","q":["An oral irrigator is best considered as:","Oral irrigator लाई कसरी बुझ्नु उपयुक्त हुन्छ?",["An adjunct to brushing and interdental cleaning","A complete replacement for brushing","A device that removes all hardened calculus","A method of sterilizing pockets"],0,"Oral irrigators can flush debris and support gingival health as an adjunct, but do not replace brushing or professional calculus removal.","Oral irrigator सहायक साधन हो; brushing वा professional calculus removal को विकल्प होइन।"]},{"topic":"Basic Periodontology I","q":["A Gracey curette is an:","Gracey curette कस्तो instrument हो?",["Area-specific periodontal curette","Universal extraction forceps","Radiographic sensor","Polishing cup"],0,"Gracey curettes are area-specific instruments designed to adapt to selected tooth surfaces.","Gracey curette निश्चित tooth surface मा मिलाएर प्रयोग गरिने area-specific periodontal instrument हो।"]},{"topic":"Basic Periodontology I","q":["The rounded toe and back of a curette mainly help to:","Curette को rounded toe र back ले मुख्यतया केमा सहयोग गर्छ?",["Improve subgingival adaptation and reduce tissue trauma","Cut gingiva aggressively","Measure tooth mobility","Hold restorative material"],0,"Rounded toe and back facilitate subgingival adaptation and reduce soft-tissue trauma.","Rounded toe र back ले subgingival adaptation सजिलो बनाउँछ र soft-tissue trauma घटाउँछ।"]},{"topic":"Basic Periodontology I","q":["A stable finger rest during scaling primarily improves:","Scaling गर्दा स्थिर finger rest ले मुख्यतया के सुधार गर्छ?",["Instrument control and safety","Radiographic contrast","Salivary secretion","Tooth eruption"],0,"A stable fulcrum improves tactile control, precision and safety during instrumentation.","स्थिर fulcrum ले instrumentation गर्दा tactile control, precision र safety बढाउँछ।"]},{"topic":"Basic Periodontology I","q":["The usual working angulation for effective hand scaling is approximately:","Hand scaling गर्दा प्रभावकारी working angulation सामान्यतया कति हुन्छ?",["70–80 degrees","0–10 degrees","20–30 degrees","90–110 degrees"],0,"A working angulation around 70–80 degrees is commonly used, with adaptation and pressure controlled for each site.","सामान्यतया ७०–८० degree working angulation प्रयोग गरिन्छ; site अनुसार adaptation र pressure नियन्त्रण गर्नुपर्छ।"]},{"topic":"Basic Periodontology I","q":["Which stroke is generally used for calculus removal with a hand instrument?","Hand instrument ले calculus हटाउँदा सामान्यतया कुन stroke प्रयोग हुन्छ?",["Controlled short pull stroke","Long uncontrolled push stroke","Random circular scraping","Forceful apical thrust"],0,"Controlled short pull strokes help remove deposits while maintaining adaptation and minimizing trauma.","नियन्त्रित छोटो pull stroke ले adaptation कायम राख्दै deposit हटाउन र trauma घटाउन मद्दत गर्छ।"]},{"topic":"Basic Periodontology I","q":["The main purpose of sharpening a periodontal instrument is to:","Periodontal instrument धार लगाउनुको मुख्य उद्देश्य के हो?",["Restore an effective cutting edge","Change instrument colour","Increase handle weight","Widen the blade"],0,"A sharp cutting edge improves efficiency and control and can reduce excessive force during instrumentation.","धारिलो cutting edge ले काम प्रभावकारी र नियन्त्रणयोग्य बनाउँछ र धेरै बल लगाउनुपर्ने आवश्यकता घटाउँछ।"]},{"topic":"Basic Periodontology I","q":["A dull periodontal instrument may:","Blunt periodontal instrument ले के गर्न सक्छ?",["Burnish or slide over deposits instead of cutting effectively","Improve tactile sensitivity automatically","Sterilize the root surface","Prevent all discomfort"],0,"A dull edge may burnish or slide over deposits, reducing removal efficiency and encouraging excessive pressure.","Blunt edge ले deposit काटेर हटाउनुको सट्टा घस्रिन सक्छ, जसले removal घटाउँछ र अनावश्यक pressure बढाउँछ।"]}]);
 // Remove exact repeated English question stems before exposing the practice and mock banks.
 const uniqueQuestions=[],seenQuestionStems=new Set();
 bank.forEach(item=>{
  const stem=String(item.q?.[0]||"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
  if(!stem||seenQuestionStems.has(stem))return;
  seenQuestionStems.add(stem);uniqueQuestions.push(item);
 });
 bank.length=0;bank.push(...uniqueQuestions);
 // Randomize answer option positions once per app session while preserving the correct answer index.
 bank.forEach(item=>{
  const options=item.q?.[2],correct=item.q?.[3];
  if(!Array.isArray(options)||!Number.isInteger(correct))return;
  const pairs=options.map((value,index)=>({value,isCorrect:index===correct}));
  for(let i=pairs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pairs[i],pairs[j]]=[pairs[j],pairs[i]];}
  item.q[2]=pairs.map(pair=>pair.value);
  item.q[3]=pairs.findIndex(pair=>pair.isCorrect);
 });
 const mcqBank=bank;
 const mockBank=bank;
 const root=document.getElementById("nhpcMcqArea");
 if(!root) return;
 let topic="सबै विषय",index=0,answers={};
 const topics=["सबै विषय",...["Human Anatomy & Physiology","Oral Anatomy & Physiology","Oral Pathology & Microbiology","Dental Pharmacy & Pharmacology","Basic Periodontology I","Basic Periodontology II","Dental Materials, Instruments & Assisting","Dental Radiography & Photography","Basic Medical Procedure & First Aid","Dental Public Health & Community Dentistry","Dental Public Health","Health Education","Epidemiology & Community Diagnosis","Office Health Management","Environmental Health","Food & Nutrition","Dental Ethics & Practice Management","Infection Prevention & Sterilization","Medical Emergencies & First Aid"]];
 const filtered=()=>topic==="सबै विषय"?mcqBank:mcqBank.filter(x=>x.topic===topic);
 function render(){
  const list=filtered(),item=list[index]; if(!item)return;
  const q=item.q,key=topic+"-"+index,chosen=answers[key];
  root.querySelector("#nhpcMcqCount").textContent=(index+1)+" / "+list.length;
  root.querySelector("#nhpcQuestion").innerHTML=`<article class="question"><div class="qtop"><span>NHPC PRACTICE • QUESTION ${index+1}</span><span>${chosen===undefined?"Not answered":"Answered"}</span></div><h3>${q[0]}</h3><p class="translation">${q[1]}</p><div class="options">${q[2].map((o,i)=>`<button class="option ${chosen!==undefined&&i===q[3]?"correct":chosen===i?"wrong":""}" data-answer="${i}" ${chosen!==undefined?"disabled":""}>${String.fromCharCode(65+i)}. ${o}</button>`).join("")}</div>${chosen!==undefined?`<div class="feedback ${chosen===q[3]?"good":"bad"}"><b>${chosen===q[3]?"सही उत्तर!":"सही उत्तर: "+q[2][q[3]]}</b><p>${q[4]}</p><p>${q[5]}</p></div>`:""}<div class="nextrow"><button class="smallbtn" id="nhpcPrev" ${index===0?"disabled":""}>अघिल्लो</button><button class="smallbtn" id="nhpcNext">${index===list.length-1?"फेरि सुरु":"अर्को प्रश्न"}</button></div></article>`;
  root.querySelectorAll("[data-answer]").forEach(b=>b.addEventListener("click",()=>{if(answers[key]!==undefined)return;answers[key]=Number(b.dataset.answer);render()}));
  root.querySelector("#nhpcPrev").addEventListener("click",()=>{index=Math.max(0,index-1);render()});
  root.querySelector("#nhpcNext").addEventListener("click",()=>{index=index===list.length-1?0:index+1;render()});
 }
 function show(){
  root.innerHTML=`<div class="section-head"><div><p class="eyebrow">NHPC QUESTION BANK</p><h3>विषयगत MCQ अभ्यास</h3></div><span class="pill">${mcqBank.length} Questions</span></div><p class="muted">सबै उपलब्ध NHPC प्रश्नहरूबाट विषय छानेर अभ्यास गर्नुहोस्। उत्तर छानेपछि सही उत्तर र व्याख्या देखिन्छ।</p><div class="dha-mcq-filters" id="nhpcFilters">${topics.map((t,i)=>`<button type="button" class="smallbtn ${i===0?"active":""}" data-topic="${t}">${i===0?"सबै विषय":t}</button>`).join("")}</div><div class="section-head"><span class="pill" id="nhpcMcqCount"></span></div><div id="nhpcQuestion"></div>`;
  root.querySelector("#nhpcFilters").addEventListener("click",e=>{const b=e.target.closest("[data-topic]");if(!b)return;topic=b.dataset.topic;index=0;root.querySelectorAll("[data-topic]").forEach(x=>x.classList.toggle("active",x===b));render()});
  render();
 }
 document.getElementById("nhpcStartMcq")?.addEventListener("click",()=>{root.classList.remove("hidden");document.getElementById("nhpcCloseMcq")?.classList.remove("hidden");show();root.scrollIntoView({behavior:"smooth",block:"start"})});
 document.getElementById("nhpcCloseMcq")?.addEventListener("click",()=>{root.classList.add("hidden");document.getElementById("nhpcCloseMcq")?.classList.add("hidden")});


 // NHPC detailed bilingual study notes: independent learning resource.
 const nhpcNotes=[["Basic Periodontology",[["Periodontium and its functions","The periodontium consists of gingiva, periodontal ligament, cementum and alveolar bone. It supports teeth, absorbs occlusal forces and maintains tooth attachment.","Periodontium का चार भाग gingiva, periodontal ligament, cementum र alveolar bone हुन्। यसले दाँतलाई अड्याउने, चपाउँदाको बल सहने र दाँतको support कायम राख्ने काम गर्छ।","Clinical focus: Identify all four tissues and assess probing depth, bleeding, recession and mobility."],["Gingivitis and periodontitis","Plaque-induced gingivitis is inflammation without periodontal attachment loss and is generally reversible. Periodontitis involves loss of attachment and supporting bone. Smoking, diabetes and poor plaque control modify risk.","Gingivitis मा गिजा सुन्निन्छ तर periodontal attachment loss हुँदैन र राम्रो plaque control ले सुधार हुन सक्छ। Periodontitis मा attachment र supporting bone क्षति हुन्छ। धूम्रपान, diabetes र कमजोर plaque control जोखिम बढाउने कारक हुन्।","Clinical focus: Do not diagnose periodontitis from bleeding alone; assess clinical attachment level and radiographic findings when indicated."]]],["Oral Pathology & Microbiology",[["Dental caries and biofilm","Dental caries is a biofilm-mediated, sugar-driven, multifactorial disease. Frequent fermentable carbohydrate exposure promotes acid production and mineral loss. Saliva and fluoride support remineralization.","Dental caries biofilm, चिनी र अन्य host/environmental factors सँग सम्बन्धित रोग हो। पटक-पटक चिनी खाँदा acid उत्पादन बढेर दाँतको mineral घट्छ। Saliva र fluoride ले remineralization मा सहयोग गर्छन्।","Clinical focus: Assess diet frequency, plaque, fluoride exposure and caries risk; reinforce prevention."],["Oral lesions and infection","Common oral conditions include candidiasis, recurrent aphthous ulcers, herpes-related lesions and traumatic ulcers. A persistent, indurated, unexplained ulcer or suspicious red/white lesion needs prompt professional assessment and referral.","मुखमा candidiasis, aphthous ulcer, herpes सम्बन्धित घाउ र चोटका ulcer देखिन सक्छन्। लामो समय निको नभएको, कडा किनारा भएको वा शंकास्पद रातो/सेतो घाउ भए तुरुन्त दन्त चिकित्सकबाट जाँच र आवश्यक referral गर्नुपर्छ।","Clinical focus: Record site, size, duration and appearance; never delay referral for a suspicious lesion."]]],["Dental Materials & Instruments",[["Dental material properties","Important properties include strength, hardness, setting time, dimensional stability, solubility and biocompatibility. Material selection depends on indication, moisture control, handling and manufacturer instructions.","मुख्य गुणहरूमा strength, hardness, setting time, dimensional stability, solubility र biocompatibility पर्छन्। कुन material प्रयोग गर्ने भन्ने कुरा उपचारको आवश्यकता, moisture control र manufacturer को निर्देशनमा निर्भर हुन्छ।","Clinical focus: Check expiry, storage, mixing ratio and manufacturer instructions before use."],["Instruments and ergonomics","A mouth mirror provides indirect vision and retraction; a periodontal probe measures sulcus or pocket depth; scalers and curettes remove deposits. Correct grasp, fulcrum and operator posture improve control and reduce injury.","Mouth mirror ले indirect vision र retraction दिन्छ; periodontal probe ले sulcus/pocket depth नाप्छ; scaler र curette ले deposit हटाउँछन्। सही grasp, fulcrum र posture ले काम सुरक्षित र प्रभावकारी बनाउँछन्।","Clinical focus: Select the correct instrument and maintain a stable fulcrum; avoid excessive force."]]],["Oral Anatomy & Physiology",[["Tooth structure and dentition","A tooth has crown, neck and root. Enamel covers the anatomical crown; dentin forms most of the tooth; pulp contains nerves and blood vessels; cementum covers the root. Primary dentition has 20 teeth and permanent dentition usually has 32 including third molars.","दाँतका crown, neck र root हुन्छन्। Enamel ले crown ढाक्छ, dentin ले धेरै भाग बनाउँछ, pulp मा nerve र blood vessel हुन्छन् र cementum ले root ढाक्छ। दूध दाँत २० र स्थायी दाँत सामान्यतया wisdom teeth सहित ३२ हुन्छन्।","Clinical focus: Know tooth surfaces, numbering, eruption patterns and differences between primary and permanent teeth."],["Saliva and oral functions","Saliva lubricates oral tissues, aids swallowing and speech, buffers acids, clears food debris and contributes antimicrobial protection and remineralization. Reduced salivary flow increases caries and mucosal discomfort risk.","लारले मुख ओसिलो राख्छ, निल्न र बोल्न सहयोग गर्छ, acid neutralize गर्छ, food debris हटाउँछ र antimicrobial protection तथा remineralization मा सहयोग गर्छ। लार कम हुँदा caries र मुख सुक्ने समस्या बढ्न सक्छ।","Clinical focus: Ask about dry mouth, medicines and hydration; assess caries risk."]]],["Dental Public Health",[["Prevention and health promotion","Primary prevention aims to prevent disease before it occurs, such as fluoride use and oral health education. Secondary prevention emphasizes early detection and timely intervention. Tertiary prevention limits complications and restores function.","Primary prevention ले रोग हुनुअघि रोक्छ, जस्तै fluoride र oral health education। Secondary prevention ले रोग चाँडै पत्ता लगाएर उपचार गर्छ। Tertiary prevention ले जटिलता घटाई कार्यक्षमता सुधार्छ।","Clinical focus: Tailor oral health education to age, literacy, culture and individual risk."],["Community oral health programmes","Community programmes begin with needs assessment, clear objectives, planning, implementation, monitoring and evaluation. School programmes may include supervised brushing, fluoride interventions and referral pathways.","समुदायमा कार्यक्रम सुरु गर्दा आवश्यकता पहिचान, उद्देश्य निर्धारण, योजना, कार्यान्वयन, अनुगमन र मूल्याङ्कन गर्नुपर्छ। विद्यालय कार्यक्रममा supervised brushing, fluoride कार्यक्रम र referral व्यवस्था हुन सक्छ।","Clinical focus: Record coverage, participation, outcomes and follow-up rather than only activities."]]],["Dental Radiography & Photography",[["Radiation protection","Use radiographs only when clinically justified. Apply ALARA/ALADA principles, optimize exposure settings, use appropriate collimation and positioning, and follow current local radiation safety requirements. Avoid repeat exposures through careful technique.","आवश्यक clinical कारण हुँदा मात्र X-ray लिनुपर्छ। ALARA/ALADA सिद्धान्त अपनाउने, सही exposure setting र positioning गर्ने तथा स्थानीय radiation safety नियम पालना गर्ने। सही technique ले दोहोर्‍याएर X-ray लिनुपर्ने अवस्था घटाउँछ।","Clinical focus: Confirm indication, patient identity and correct image receptor placement before exposure."],["Image quality and documentation","Diagnostic images should show the required anatomy with appropriate density, contrast, sharpness and minimal distortion. Clinical photographs require consent, secure storage and consistent views when used for monitoring.","Diagnostic image मा आवश्यक anatomy स्पष्ट, उचित density/contrast/sharpness र न्यून distortion हुनुपर्छ। Clinical photo खिच्दा consent, सुरक्षित storage र monitoring का लागि मिल्दोजुल्दो view आवश्यक हुन्छ।","Clinical focus: Follow infection control for sensors and maintain patient confidentiality."]]],["Dental Pharmacy",[["Safe medication practice","Check the medication name, indication, dose, route, timing, allergies, contraindications and relevant medical history. Follow the prescriber’s instructions and local scope-of-practice rules; do not prescribe outside authorization.","औषधिको नाम, कारण, मात्रा, दिने बाटो, समय, allergy, contraindication र medical history जाँच्नुपर्छ। Prescriber को निर्देशन र आफ्नो professional scope पालना गर्नुपर्छ; अधिकारबाहिर औषधि prescribe गर्नु हुँदैन।","Clinical focus: Clarify allergies and current medicines; document and report adverse reactions."],["Local anaesthesia and emergencies","Before local anaesthesia, review medical history, allergies, medications and relevant precautions. Recognize early signs of adverse reactions or toxicity and activate the clinic emergency protocol; maintain appropriate emergency equipment and training.","Local anaesthesia अघि medical history, allergy, औषधि र आवश्यक सावधानी बुझ्नुपर्छ। Adverse reaction वा toxicity का प्रारम्भिक संकेत चिन्नु र clinic emergency protocol सुरु गर्नु आवश्यक हुन्छ।","Clinical focus: Never exceed authorized duties; know emergency response roles and escalation steps."]]],["Food and Nutrition",[["Diet and oral health","Frequency of free-sugar intake is an important caries risk factor. Encourage water, balanced meals and limiting sugary snacks and drinks between meals. Nutritional advice should be practical and culturally appropriate.","Free sugar कति पटक खाइन्छ भन्ने कुरा caries risk का लागि महत्त्वपूर्ण हुन्छ। पानी, सन्तुलित खाना र खानाबीच मीठा snacks/drinks कम गर्न प्रोत्साहन गर्नुपर्छ। पोषण सल्लाह व्यवहारिक र स्थानीय खानासँग मिल्ने हुनुपर्छ।","Clinical focus: Ask about frequency and timing of sugar exposure, not only total quantity."],["Nutrients and oral tissues","Protein supports tissue growth and repair; calcium and phosphorus contribute to mineralized tissues; vitamin D supports calcium regulation; vitamin C is important for collagen formation. Deficiency may affect oral and general health.","Protein ले tissue growth र repair मा सहयोग गर्छ; calcium र phosphorus mineralized tissue का लागि, vitamin D calcium regulation का लागि र vitamin C collagen बनाउन महत्त्वपूर्ण हुन्छ। कमी हुँदा मुख र समग्र स्वास्थ्यमा असर पर्न सक्छ।","Clinical focus: Refer suspected nutritional deficiency for appropriate medical or nutrition assessment."]]],["Epidemiology & Community Diagnosis",[["Basic epidemiological measures","Incidence measures new cases arising in a population at risk over a specified period. Prevalence measures all existing cases at a particular time or over a period. A clear numerator, denominator and time frame are essential.","Incidence ले निश्चित समयमा नयाँ रोगी कति थपिए भन्ने जनाउँछ। Prevalence ले कुनै समय वा अवधिमा रहेका सबै रोगी जनाउँछ। Numerator, denominator र समय स्पष्ट हुनुपर्छ।","Clinical focus: Check the population, case definition and time period before interpreting a rate."],["Community diagnosis and survey","A community diagnosis identifies oral health needs, determinants, available resources and priority groups. A survey requires a defined objective, sampling approach, standardized examination criteria, ethical consent and reliable data recording.","Community diagnosis ले मुख स्वास्थ्य आवश्यकता, कारण, उपलब्ध स्रोत र प्राथमिक समूह पहिचान गर्छ। Survey गर्दा स्पष्ट उद्देश्य, sampling, standard examination criteria, ethical consent र सही data recording आवश्यक हुन्छ।","Clinical focus: Use findings to set measurable priorities and evaluate programme impact."]]],["Dental Ethics & Practice Management",[["Consent and confidentiality","Valid informed consent requires understandable information about the proposed procedure, benefits, material risks and alternatives, with an opportunity to ask questions and decide voluntarily. Protect patient records and share information only with proper authorization or legal basis.","सही informed consent का लागि उपचार, फाइदा, जोखिम र विकल्प बुझिने भाषामा बताउनुपर्छ। बिरामीलाई प्रश्न गर्ने र स्वेच्छाले निर्णय गर्ने अवसर दिनुपर्छ। Patient record गोप्य राख्नुपर्छ।","Clinical focus: Document consent, refusal, relevant discussions and authorized disclosures."],["Professional conduct and records","Work within competence and legal scope, maintain accurate contemporaneous records, follow infection prevention policies, communicate respectfully and refer when a case exceeds competence.","आफ्नो सीप र कानुनी कार्यक्षेत्रभित्र काम गर्ने, समयमै सही record राख्ने, infection prevention पालना गर्ने, सम्मानपूर्वक संवाद गर्ने र आफ्नो क्षमताभन्दा बाहिरको समस्या referral गर्ने।","Clinical focus: Never alter records retrospectively without a transparent dated correction."]]],["Infection Prevention & Sterilization",[["Standard precautions","Treat blood and body fluids as potentially infectious. Perform hand hygiene, use appropriate PPE, practice safe sharps handling, clean and disinfect environmental surfaces, and reprocess reusable instruments according to validated instructions.","रगत र शरीरका तरल पदार्थलाई सम्भावित संक्रमणयुक्त मानेर सावधानी अपनाउनुपर्छ। Hand hygiene, PPE, sharps safety, सतह सफाइ र reusable instruments को सही reprocessing आवश्यक हुन्छ।","Clinical focus: Use a puncture-resistant sharps container and never recap needles with two hands."],["Instrument reprocessing","Reusable critical instruments that penetrate soft tissue or bone require cleaning followed by validated sterilization. Monitor sterilization cycles with physical, chemical and biological indicators as required by policy; store packs dry and intact.","Soft tissue वा bone छेड्ने reusable critical instrument सफा गरेपछि validated sterilization गर्नुपर्छ। नीति अनुसार physical, chemical र biological indicator प्रयोग गरी cycle monitor गर्नुपर्छ। Pack सुक्खा र नफुटेको अवस्थामा राख्नुपर्छ।","Clinical focus: A failed indicator or compromised pack means the instruments must not be considered sterile."]]],["Medical Emergencies & First Aid",[["Recognition and initial response","Recognize deterioration early, stop dental treatment, call for help, assess responsiveness and breathing, and activate the clinic emergency plan. Provide basic life support within current training and local protocol.","अवस्था बिग्रिएको चाँडै चिन्नु, उपचार रोक्नु, सहयोग बोलाउनु, responsiveness र breathing जाँच्नु र clinic emergency plan सुरु गर्नु। आफ्नो तालिम र स्थानीय protocol अनुसार BLS दिनुपर्छ।","Clinical focus: Ensure emergency numbers, oxygen/AED where available, and team roles are known."],["Syncope and anaphylaxis","For suspected syncope, stop treatment, position the patient safely and assess airway, breathing and circulation. Suspected anaphylaxis is a life-threatening emergency requiring immediate emergency activation and prompt intramuscular adrenaline by trained authorized personnel according to protocol.","Syncope शंका भए उपचार रोक्ने, बिरामीलाई सुरक्षित position मा राख्ने र airway, breathing, circulation जाँच्ने। Anaphylaxis जीवन-जोखिमयुक्त emergency हो; तुरुन्त सहायता बोलाई तालिमप्राप्त अधिकृत व्यक्तिले protocol अनुसार IM adrenaline दिनुपर्छ।","Clinical focus: Do not delay emergency transfer or treatment while waiting for symptoms to resolve."]]],...[["Human Anatomy & Physiology",[["Major body systems","The NHPC core syllabus includes integumentary, skeletal, muscular, nervous, endocrine, blood, cardiovascular, lymphatic, digestive, respiratory, urinary and reproductive systems, plus growth and development.","NHPC core syllabus मा छाला, हड्डी, मांसपेशी, स्नायु, endocrine, रगत, मुटु/रक्तसञ्चार, lymphatic, पाचन, श्वासप्रश्वास, मूत्र र प्रजनन प्रणाली तथा वृद्धि-विकास पर्छन्।","Clinical focus: Relate diabetes, cardiovascular disease, bleeding disorders and immune status to safe dental care."],["Blood and immunity","Blood contains plasma, red cells, white cells and platelets. Haemoglobin transports oxygen; white cells support defence; platelets contribute to clotting. The lymphatic system supports fluid balance and immunity.","रगतमा plasma, red cells, white cells र platelets हुन्छन्। Haemoglobin ले अक्सिजन ओसार्छ, white cells ले रोगसँग लड्छन् र platelets ले clotting मा सहयोग गर्छन्। Lymphatic प्रणालीले fluid balance र immunity मा भूमिका खेल्छ।","Clinical focus: Ask about anaemia, bleeding problems, anticoagulants and immune compromise before treatment."]]],["Basic Periodontology I",[["Gingival anatomy and attachment","The gingiva includes free, attached and interdental gingiva. The junctional epithelium forms an epithelial attachment to the tooth. Gingival connective tissue contains collagen fibres, vessels, nerves and ground substance.","Gingiva मा free, attached र interdental भाग हुन्छन्। Junctional epithelium ले दाँतसँग epithelial attachment बनाउँछ। Gingival connective tissue मा collagen fibre, रक्तनली, स्नायु र ground substance हुन्छ।","Clinical focus: Identify normal gingival colour, contour, consistency, sulcus and attachment during examination."],["Dental biofilm and calculus","Dental biofilm is an organized microbial community embedded in a matrix. It develops on tooth surfaces and may mineralize into calculus. Calculus retains biofilm and contributes to periodontal inflammation.","Dental biofilm दाँतको सतहमा matrix भित्र रहने व्यवस्थित सूक्ष्मजीव समुदाय हो। यो mineralize भएर calculus बन्न सक्छ। Calculus ले biofilm थामेर periodontal inflammation मा योगदान दिन्छ।","Clinical focus: Explain plaque control and distinguish soft biofilm from mineralized calculus."]]],["Basic Periodontology II",[["Periodontal pocket and attachment loss","A periodontal pocket is a pathologically deepened gingival sulcus. Assessment includes probing depth, gingival margin position, clinical attachment level, bleeding, suppuration, mobility and radiographic bone levels when indicated.","Periodontal pocket भनेको रोगका कारण गहिरिएको gingival sulcus हो। जाँचमा probing depth, gingival margin, clinical attachment level, bleeding, pus, mobility र आवश्यक परे X-ray मा bone level हेरिन्छ।","Clinical focus: Record six sites per tooth when indicated and interpret findings with the full clinical picture."],["Periodontal treatment sequence","Periodontal care includes diagnosis, risk-factor control, oral hygiene instruction, supra/subgingival instrumentation when indicated, reassessment, maintenance and referral for complex disease.","Periodontal care मा diagnosis, जोखिम नियन्त्रण, oral hygiene instruction, आवश्यकताअनुसार instrumentation, पुनःमूल्याङ्कन, maintenance र जटिल अवस्थामा referral पर्छ।","Clinical focus: Reassess healing and reinforce long-term supportive periodontal care."]]],["Basic Medical Procedure & First Aid",[["History and vital signs","A medical history identifies systemic disease, allergies, medicines and previous adverse events. Physical assessment may include pulse, blood pressure, respiratory rate, temperature and general appearance as appropriate.","Medical history ले systemic रोग, allergy, औषधि र पहिले भएका adverse event पहिचान गर्छ। आवश्यकताअनुसार pulse, blood pressure, श्वासदर, तापक्रम र सामान्य अवस्था जाँचिन्छ।","Clinical focus: Recognize when abnormal findings require postponement, medical consultation or emergency response."],["Basic life support","For an unresponsive person, ensure scene safety, check response and breathing, call emergency help and obtain an AED if available. If the person is not breathing normally, begin CPR according to current certified training.","बेहोस व्यक्तिमा पहिले सुरक्षा सुनिश्चित गर्ने, response र breathing जाँच्ने, emergency सहायता बोलाउने र उपलब्ध भए AED ल्याउने। सामान्य श्वास नभए हालको प्रमाणित तालिमअनुसार CPR सुरु गर्ने।","Clinical focus: Follow current national/local protocols and refresh practical BLS skills regularly."]]],["Health Education",[["Communication and teaching methods","Health education uses clear, culturally appropriate communication. Methods include individual counselling, group discussion, demonstration, role play and mass media. Select methods according to audience needs.","स्वास्थ्य शिक्षामा स्पष्ट र संस्कृतिअनुकूल संवाद चाहिन्छ। Individual counselling, group discussion, demonstration, role play र mass media विधि हुन्। लक्षित समूहको आवश्यकता अनुसार विधि छान्नुपर्छ।","Clinical focus: Use teach-back to confirm that the patient understood the advice."],["Planning and evaluation","A health education programme should define its target group, needs, SMART objectives, content, methods, resources, schedule and indicators. Evaluation measures reach, learning and behaviour or health outcomes.","स्वास्थ्य शिक्षा कार्यक्रममा लक्षित समूह, आवश्यकता, SMART उद्देश्य, सामग्री, विधि, स्रोत, समयतालिका र सूचक तोकिनुपर्छ। मूल्याङ्कनले पहुँच, सिकाइ र व्यवहार/स्वास्थ्य नतिजा हेर्छ।","Clinical focus: Record measurable outcomes rather than counting only sessions delivered."]]],["Office Health Management",[["Health information and records","Accurate records support continuity, reporting, planning, quality improvement and accountability. Maintain confidentiality, correct patient identification, legible entries and secure storage.","सही अभिलेखले उपचार निरन्तरता, reporting, योजना, गुणस्तर सुधार र जवाफदेहितामा सहयोग गर्छ। गोपनीयता, सही बिरामी पहिचान, स्पष्ट लेखाइ र सुरक्षित भण्डारण कायम गर्नुपर्छ।","Clinical focus: Document findings, consent, treatment, advice, referrals and follow-up."],["Logistics and camp management","Service planning includes staffing, supplies, equipment, transport, infection prevention, patient flow, referral arrangements, budgeting and post-camp reporting.","सेवा योजनामा जनशक्ति, सामग्री, उपकरण, यातायात, infection prevention, बिरामी प्रवाह, referral, बजेट र शिविरपछिको प्रतिवेदन पर्छ।","Clinical focus: Check stock, expiry, equipment function and emergency readiness before outreach services."]]],["Environmental Health",[["Water, sanitation and hygiene","Safe water, sanitary latrines, hand hygiene, food safety and proper waste management reduce infectious disease transmission. Protect water sources and store treated water in clean covered containers.","सुरक्षित पानी, स्वच्छ शौचालय, हात सफाइ, खाद्य सुरक्षा र उचित फोहोर व्यवस्थापनले संक्रमण घटाउँछन्। पानीको स्रोत जोगाउने र प्रशोधित पानी सफा छोपिएको भाँडोमा राख्ने।","Clinical focus: Apply hand hygiene and environmental cleaning in dental care settings."],["Vectors and environmental hazards","Vectors such as mosquitoes and flies can transmit disease. Control measures include eliminating breeding sites, covering water containers, safe waste disposal and appropriate vector-control programmes.","लामखुट्टे र झिँगाजस्ता vector ले रोग सार्न सक्छन्। प्रजननस्थल हटाउने, पानीका भाँडा छोप्ने, सुरक्षित फोहोर व्यवस्थापन र उपयुक्त नियन्त्रण कार्यक्रम आवश्यक हुन्छ।","Clinical focus: Recognize local environmental risks and provide practical prevention advice."]]],["Dental Public Health",[["Extraction and post-extraction care","Before extraction, assess history, indication, contraindications, consent and relevant risks. After extraction, provide instructions on pressure for haemostasis, clot protection, oral hygiene, diet, warning signs and review/referral.","दाँत निकाल्नुअघि history, indication, contraindication, consent र जोखिम जाँच्नुपर्छ। निकालेपछि रक्तस्राव रोक्न pressure, clot जोगाउने, मुख सफाइ, खाना, चेतावनी लक्षण र follow-up बारे सल्लाह दिनुपर्छ।","Clinical focus: Persistent bleeding, spreading infection or systemic deterioration requires urgent assessment/referral."],["Infection prevention in dentistry","Standard precautions include hand hygiene, appropriate PPE, safe injection practice, instrument cleaning and validated sterilization, environmental cleaning and segregation of clinical waste.","Standard precaution मा हात सफाइ, उपयुक्त PPE, सुरक्षित injection, instrument सफाइ र प्रमाणित sterilization, वातावरण सफाइ तथा clinical waste छुट्याउने काम पर्छ।","Clinical focus: Treat every patient with standard precautions and follow the facility's infection-control policy."]]]]];

 nhpcNotes[13][1].push(
 ["Gingival histology and sulcus","Gingiva includes oral, sulcular and junctional epithelial components. The junctional epithelium attaches to the tooth through an internal basal lamina and hemidesmosomes. Gingival connective tissue contains collagen fibres, vessels, nerves and ground substance.","Gingiva मा oral, sulcular र junctional epithelium हुन्छन्। Junctional epithelium internal basal lamina र hemidesmosome मार्फत दाँतसँग जोडिन्छ। Connective tissue मा collagen fibre, रक्तनली, स्नायु र ground substance हुन्छ।","Clinical focus: Relate healthy gingival appearance to probing findings and recognize changes requiring referral."],
 ["Biofilm formation and calculus","A salivary acquired pellicle forms first on a cleaned tooth surface. Early colonizers attach and multiply; co-aggregation and maturation follow. Plaque mineralization forms calculus, which retains biofilm.","सफा दाँतमा पहिले saliva बाट acquired pellicle बन्छ। त्यसमा प्रारम्भिक bacteria टाँसिएर बढ्छन् र biofilm परिपक्व हुन्छ। Plaque mineralize हुँदा calculus बन्छ, जसले biofilm अड्काउन सक्छ।","Clinical focus: Explain daily biofilm disruption and why calculus requires professional instrumentation."],
 ["Dentifrices and therapeutic agents","Dentifrices may contain abrasives, detergents, humectants, binders, flavouring and therapeutic ingredients. Fluoride promotes remineralization and reduces demineralization. Desensitizing agents may reduce dentinal tubule fluid movement or nerve excitability.","Dentifrice मा abrasive, detergent, humectant, binder, flavour र therapeutic ingredient हुन सक्छन्। Fluoride ले remineralization बढाउँछ। Desensitizing agent ले dentinal tubule मा तरलको movement वा nerve excitability घटाउन सक्छ।","Clinical focus: Select products according to caries risk, sensitivity, age and professional guidance."],
 ["Periodontal instrumentation and ergonomics","Effective instrumentation depends on patient and operator position, stable fulcrum, correct grasp, adaptation, working angulation and controlled strokes. Area-specific curettes are selected for particular surfaces. Ultrasonic tips require light pressure, movement and adequate irrigation.","प्रभावकारी instrumentation का लागि सही position, स्थिर fulcrum, grasp, adaptation, angulation र नियन्त्रित stroke चाहिन्छ। Area-specific curette निश्चित surface का लागि छानिन्छ। Ultrasonic tip हल्का pressure, निरन्तर movement र पर्याप्त irrigation सहित प्रयोग गर्नुपर्छ।","Clinical focus: Use appropriate instruments within training and scope; avoid excessive force and prolonged stationary ultrasonic contact."],
 ["Instrument sharpening and maintenance","A sharp cutting edge improves tactile control and deposit removal. Inspect blades, use a suitable sharpening stone and maintain the original blade design. Follow validated cleaning, packaging and sterilization procedures after use.","धारिलो cutting edge ले tactile control र deposit removal सुधार्छ। Blade जाँच्ने, उपयुक्त sharpening stone प्रयोग गर्ने र मूल blade design कायम राख्ने। प्रयोगपछि validated cleaning, packaging र sterilization पालना गर्ने।","Clinical focus: Remove damaged instruments from service and document reprocessing as required."]
 );
 // Additional bilingual notes mapped to the official PCL Dental Hygiene syllabus.
 nhpcNotes[0][1].push(["Plaque biofilm and calculus","Dental plaque is an organized microbial biofilm attached to tooth surfaces. If not disrupted, it can mineralize into calculus. Supragingival and subgingival deposits contribute to periodontal inflammation and require appropriate professional removal.","Dental plaque दाँतको सतहमा टाँसिएको सूक्ष्मजीवको biofilm हो। समयमै हटाइएन भने mineralize भएर calculus बन्न सक्छ। Supragingival र subgingival deposit ले periodontal inflammation बढाउन सक्छ र उचित professional removal आवश्यक पर्न सक्छ।","Clinical focus: Explain daily mechanical plaque control and identify deposits during examination."]);
 nhpcNotes[1][1].push(["Caries process and pulpal response","Caries develops through repeated cycles of demineralization and remineralization in a susceptible tooth exposed to cariogenic biofilm and fermentable carbohydrates. Lesion depth and pulpal symptoms guide referral and treatment planning.","Caries जोखिमयुक्त दाँतमा cariogenic biofilm र fermentable carbohydrate को बारम्बार सम्पर्कबाट demineralization र remineralization को चक्र बिग्रँदा विकास हुन्छ। Lesion को गहिराइ र pulp सम्बन्धी लक्षणले referral तथा treatment planning मा सहयोग गर्छ।","Clinical focus: Record lesion site and symptoms; refer promptly when pain, swelling or pulpal involvement is suspected."]);
 nhpcNotes[2][1].push(["Impression materials and gypsum products","Impression materials reproduce oral structures for study or treatment. Alginate is an irreversible hydrocolloid; gypsum products are used to pour casts. Accurate proportions, mixing, disinfection and timely pouring help preserve detail.","Impression material ले मुखको संरचनाको प्रतिरूप बनाउँछ। Alginate irreversible hydrocolloid हो र gypsum cast बनाउन प्रयोग हुन्छ। सही अनुपात, mixing, disinfection र समयमा pouring गर्दा detail सुरक्षित रहन्छ।","Clinical focus: Follow manufacturer instructions for water-powder ratio, working time, disinfection and storage."]);
 nhpcNotes[3][1].push(["Cranial nerves and mastication","The trigeminal nerve (cranial nerve V) provides major sensory supply to the face and oral structures and motor supply to muscles of mastication. The facial nerve (VII) supplies muscles of facial expression and carries taste from the anterior two-thirds of the tongue.","Trigeminal nerve (cranial nerve V) ले अनुहार तथा मुखका धेरै भागमा sensory supply र mastication का मांसपेशीमा motor supply दिन्छ। Facial nerve (VII) ले अनुहारका expression muscles चलाउँछ र जिब्रोको अगाडिको दुई-तिहाइ भागको taste बोक्छ।","Clinical focus: Understand nerve functions relevant to oral examination and local anaesthesia."]);
 nhpcNotes[4][1].push(["Oral health indicators and survey","Common oral health indicators include caries experience, periodontal status, oral hygiene and treatment needs. Standardized diagnostic criteria, calibrated examiners and consistent recording improve survey validity and comparison.","मुख स्वास्थ्यका सूचकमा caries अनुभव, periodontal अवस्था, oral hygiene र उपचार आवश्यकता पर्छन्। Standardized criteria, प्रशिक्षित examiner र एउटै तरिकाको recording ले survey को विश्वसनीयता र तुलना गर्ने क्षमता बढाउँछ।","Clinical focus: Use the prescribed index and record findings consistently; do not change criteria midway."]);
 nhpcNotes[5][1].push(["Intraoral radiographic image quality","Diagnostic image quality depends on receptor placement, beam angulation, exposure factors, patient cooperation and processing or digital handling. Incorrect horizontal angulation may cause overlap; incorrect vertical angulation may cause elongation or foreshortening.","Diagnostic image quality receptor placement, beam angulation, exposure factor, बिरामीको सहयोग र processing वा digital handling मा निर्भर हुन्छ। गलत horizontal angulation ले overlap र गलत vertical angulation ले elongation वा foreshortening गराउन सक्छ।","Clinical focus: Check image quality and clinical need before considering any repeat exposure."]);
 nhpcNotes[6][1].push(["Safe medication principles in dentistry","Dental medicines should be selected according to indication, patient history, allergies, current medicines, age, pregnancy status where relevant and applicable prescribing authority. Check dose, route, frequency, duration and expiry; monitor for adverse reactions.","दन्त उपचारमा औषधि indication, बिरामीको history, allergy, हालका औषधि, उमेर र आवश्यकताअनुसार pregnancy status तथा prescribing authority अनुसार छनोट गर्नुपर्छ। Dose, route, frequency, duration र expiry जाँच्नुहोस् र adverse reaction निगरानी गर्नुहोस्।","Clinical focus: Do not prescribe outside your legal scope; clarify allergies and refer or escalate suspected adverse reactions."]);
 nhpcNotes[7][1].push(["Dietary sugars and oral health","Frequency of free-sugar exposure is an important caries risk factor. Repeated between-meal sugary snacks and drinks increase acid challenges. Water, balanced meals and reducing the frequency of sugary exposures support prevention.","Free sugar सेवनको frequency caries जोखिमको महत्त्वपूर्ण कारक हो। खानाबीच पटक-पटक गुलियो snacks र drinks सेवन गर्दा acid attack बढ्छ। पानी, सन्तुलित खाना र गुलियो सेवनको frequency घटाउँदा रोकथाममा सहयोग हुन्छ।","Clinical focus: Give practical, non-judgmental dietary advice based on the patient's usual eating pattern."]);
 nhpcNotes[8][1].push(["Epidemiological study designs","Descriptive studies summarize disease by person, place and time. Analytical studies examine associations, while experimental studies evaluate interventions. Study design should match the research question and ethical requirements.","Descriptive study ले रोगलाई व्यक्ति, स्थान र समयअनुसार वर्णन गर्छ। Analytical study ले सम्बन्ध जाँच्छ र experimental study ले intervention मूल्याङ्कन गर्छ। Study design अनुसन्धान प्रश्न र ethical requirement अनुसार हुनुपर्छ।","Clinical focus: Distinguish incidence, prevalence and study design when interpreting community data."]);
 nhpcNotes[9][1].push(["Professional ethics and confidentiality","Dental professionals should respect patient dignity, obtain informed consent, maintain confidentiality, keep accurate records and work within their competence and legal scope. Information is shared only with appropriate authorization or lawful justification.","दन्त स्वास्थ्यकर्मीले बिरामीको सम्मान, informed consent, confidentiality, सही record र आफ्नो क्षमता तथा कानुनी scope भित्र काम गर्नुपर्छ। उचित अनुमति वा कानुनी आधारबिना बिरामीको सूचना अरूसँग साझा गर्नु हुँदैन।","Clinical focus: Explain procedures clearly, document consent and seek supervision when a task is beyond competence."]);
 nhpcNotes[10][1].push(["Instrument reprocessing sequence","Reusable instruments require safe transport, cleaning, inspection, packaging, sterilization, monitoring and appropriate storage according to validated protocols. Cleaning must precede sterilization because residual soil can interfere with the process.","पुनःप्रयोग हुने instrument लाई सुरक्षित transport, cleaning, inspection, packaging, sterilization, monitoring र उचित storage गर्नुपर्छ। Sterilization अघि cleaning आवश्यक हुन्छ, किनकि बाँकी फोहोरले sterilization प्रभावकारी हुन नदिन सक्छ।","Clinical focus: Follow the facility's validated cycle, load instructions, indicators and documentation."]);
 nhpcNotes[11][1].push(["Syncope and initial response","Syncope is a transient loss of consciousness due to temporary reduction in cerebral perfusion. Stop treatment, protect the patient from injury, assess responsiveness and airway-breathing-circulation, and follow the emergency protocol if recovery is not prompt.","Syncope मस्तिष्कमा अस्थायी रूपमा रक्तप्रवाह घट्दा हुने छोटो समयको चेतना गुम्ने अवस्था हो। उपचार रोक्नुहोस्, चोटबाट जोगाउनुहोस्, responsiveness र ABC जाँच्नुहोस्; छिटो सुधार नभए emergency protocol अपनाउनुहोस्।","Clinical focus: Recognize warning signs, summon help and never leave an unresponsive patient unattended."]);
 nhpcNotes[12][1].push(["Blood and cardiovascular system","Blood transports oxygen, nutrients, hormones and waste products. The heart and blood vessels maintain circulation; blood pressure reflects the force of blood against arterial walls and should be measured with correct technique.","रगतले oxygen, पोषक तत्त्व, hormone र waste पदार्थ ओसार्छ। मुटु र रक्तनलीले circulation कायम गर्छन्। Blood pressure ले धमनीको भित्तामा रगतले दिने दबाब जनाउँछ र सही technique ले मापन गर्नुपर्छ।","Clinical focus: Record vital signs accurately and escalate abnormal findings according to clinical protocol."]);
 nhpcNotes[13][1].push(["Gingival anatomy and healthy features","Healthy gingiva is generally firm, resilient and adapted around the teeth, with color varying by natural pigmentation and tissue characteristics. The gingival sulcus is a shallow space between the tooth and free gingiva; its depth is assessed with a periodontal probe.","स्वस्थ gingiva सामान्यतया firm र resilient हुन्छ र दाँत वरिपरि मिलेर बसेको हुन्छ; यसको रङ प्राकृतिक pigmentation र tissue अनुसार फरक हुन सक्छ। Gingival sulcus दाँत र free gingiva बीचको सानो space हो, जसको गहिराइ periodontal probe ले जाँचिन्छ।","Clinical focus: Assess color, contour, consistency, bleeding and probing findings together rather than relying on color alone."]);
 nhpcNotes[14][1].push(["Periodontal pocket and attachment","A periodontal pocket is a pathologically deepened gingival sulcus associated with loss of periodontal support. Clinical attachment level relates the base of the pocket to the cemento-enamel junction and helps assess tissue support.","Periodontal pocket भनेको periodontal support घटेसँग सम्बन्धित गहिरिएको gingival sulcus हो। Clinical attachment level ले pocket को आधारलाई cemento-enamel junction सँग तुलना गरी tissue support मूल्याङ्कन गर्न मद्दत गर्छ।","Clinical focus: Record probing depths and gingival margin position systematically at the required sites."]);
 nhpcNotes[15][1].push(["Basic medical history and vital signs","A focused medical history includes current conditions, medicines, allergies, previous adverse events and relevant medical or dental history. Vital signs commonly include blood pressure, pulse, respiratory rate and temperature when indicated.","Focused medical history मा हालका रोग, औषधि, allergy, पहिले भएका adverse event र सम्बन्धित medical वा dental history पर्छन्। आवश्यकताअनुसार blood pressure, pulse, respiratory rate र temperature जस्ता vital signs लिइन्छ।","Clinical focus: Confirm identity, update history at each relevant visit and escalate red flags before treatment."]);
 nhpcNotes[16][1].push(["Health education planning cycle","Effective health education identifies the target group and needs, sets measurable objectives, selects suitable messages and methods, implements activities and evaluates outcomes. Feedback is used to improve the next cycle.","प्रभावकारी health education मा लक्षित समूह र आवश्यकता पहिचान, मापनयोग्य उद्देश्य, उपयुक्त सन्देश र विधि छनोट, कार्यान्वयन र परिणाम मूल्याङ्कन गरिन्छ। Feedback प्रयोग गरी अर्को चरण सुधारिन्छ।","Clinical focus: Evaluate knowledge or behaviour change, not only the number of sessions conducted."]);
 nhpcNotes[17][1].push(["Health information system and reporting","A health information system collects, checks, analyzes and uses service data for planning, monitoring and decision-making. Accurate, timely and complete reporting supports resource allocation and service improvement.","Health information system ले सेवा सम्बन्धी data संकलन, जाँच, विश्लेषण र योजना, monitoring तथा निर्णयका लागि प्रयोग गर्छ। सही, समयमै र पूर्ण reporting ले स्रोत बाँडफाँट र सेवा सुधारमा सहयोग गर्छ।","Clinical focus: Maintain legible records, protect confidentiality and submit reports through the approved channel."]);
 nhpcNotes[18][1].push(["Safe water and sanitation","Safe water requires protection at source, appropriate treatment, hygienic storage and prevention of recontamination. Sanitation and hand hygiene reduce transmission of fecal-oral and other infections.","सुरक्षित पानीका लागि स्रोत संरक्षण, उचित treatment, सफा भण्डारण र पुनःदूषण रोकथाम आवश्यक हुन्छ। सरसफाइ र हात धुने बानीले fecal-oral तथा अन्य संक्रमण सर्न कम गर्छ।","Clinical focus: Promote safe water handling, handwashing and hygienic sanitation practices in the community."]);
 nhpcNotes[19][1].push(["Dental public health programme evaluation","Programme evaluation compares planned objectives with implementation and results. Process indicators describe delivery and coverage; outcome indicators assess changes in knowledge, behaviour or oral health status.","कार्यक्रम मूल्याङ्कनले योजना गरिएका उद्देश्यलाई कार्यान्वयन र परिणामसँग तुलना गर्छ। Process indicator ले सेवा वितरण र coverage देखाउँछ; outcome indicator ले ज्ञान, व्यवहार वा मुख स्वास्थ्यको परिवर्तन मूल्याङ्कन गर्छ।","Clinical focus: Use baseline data, measurable indicators and follow-up findings to improve the programme."]);
 const notesRoot=document.getElementById("nhpcNotesArea");
 function renderNhpcNotes(){
  notesRoot.classList.remove("hidden");
  document.getElementById("nhpcCloseNotes")?.classList.remove("hidden");
  document.getElementById("nhpcMcqArea")?.classList.add("hidden");
  document.getElementById("nhpcFullMock")?.classList.add("hidden");
  document.getElementById("nhpcCloseMcq")?.classList.add("hidden");
  document.getElementById("nhpcCloseMock")?.classList.add("hidden");
  notesRoot.innerHTML=`<div class="section-head"><div><p class="eyebrow">BILINGUAL STUDY LIBRARY</p><h3>NHPC Detailed Study Notes</h3></div><span class="pill">२० विषय</span></div><p class="muted">प्रत्येक विषयमा English concept, नेपाली व्याख्या र Clinical focus समावेश गरिएको छ।</p><input id="nhpcNotesSearch" type="search" class="form-control" placeholder="Search notes in English or नेपाली..." aria-label="Search study notes"><div class="dha-mcq-filters" id="nhpcNotesFilters">${nhpcNotes.map((t,i)=>`<button class="smallbtn ${i===0?"active":""}" data-notes-topic="${i}" type="button">${t[0]}</button>`).join("")}</div><div id="nhpcNotesContent" aria-live="polite"></div>`;
  const content=notesRoot.querySelector("#nhpcNotesContent");
  const renderCards=(items,heading)=>{content.innerHTML=`<h3>${heading}</h3><div class="notes-list">${items.map(x=>`<article class="note"><h3>${x.topic?x.topic+" — ":""}${x.note[0]}</h3><p><b>English:</b> ${x.note[1]}</p><p class="np"><b>नेपाली:</b> ${x.note[2]}</p><div class="clinical-point"><b>Clinical focus:</b> ${x.note[3].replace("Clinical focus: ","")}</div></article>`).join("")}</div>`;};
  const showTopic=i=>{const t=nhpcNotes[i];notesRoot.querySelectorAll("[data-notes-topic]").forEach(b=>b.classList.toggle("active",Number(b.dataset.notesTopic)===i));renderCards(t[1].map(note=>({note})),t[0]);};
  const search=notesRoot.querySelector("#nhpcNotesSearch");
  search.addEventListener("input",()=>{const q=search.value.trim().toLocaleLowerCase();if(!q){showTopic(0);return;}notesRoot.querySelectorAll("[data-notes-topic]").forEach(b=>b.classList.remove("active"));const matches=[];nhpcNotes.forEach(t=>t[1].forEach(note=>{if((t[0]+" "+note.join(" ")).toLocaleLowerCase().includes(q))matches.push({topic:t[0],note});}));renderCards(matches,matches.length?"Search results ("+matches.length+")":"No matching notes found");if(!matches.length)content.innerHTML='<p class="muted">यो शब्दसँग मिल्ने Notes भेटिएन। फरक शब्द प्रयोग गरेर खोज्नुहोस्।</p>';});
  notesRoot.querySelector("#nhpcNotesFilters").addEventListener("click",e=>{const b=e.target.closest("[data-notes-topic]");if(b){search.value="";showTopic(Number(b.dataset.notesTopic));}});
  showTopic(0);
  notesRoot.scrollIntoView({behavior:"smooth",block:"start"});
 }
 document.getElementById("nhpcStartNotes")?.addEventListener("click",renderNhpcNotes);
 document.getElementById("nhpcCloseNotes")?.addEventListener("click",()=>{notesRoot.classList.add("hidden");document.getElementById("nhpcCloseNotes")?.classList.add("hidden")});
 // NHPC student progress summary, based on locally saved mock-test attempts.
 function renderNhpcProgress(){
  const box=document.getElementById("nhpcProgress");if(!box)return;
  let rows=[];try{rows=JSON.parse(localStorage.getItem("dhpn-mock-history")||"[]")}catch(e){}
  rows=rows.filter(r=>(r.module||"").toLowerCase().includes("nhpc"));
  const avg=rows.length?Math.round(rows.reduce((s,r)=>s+r.percent,0)/rows.length):0,best=rows.length?Math.max(...rows.map(r=>r.percent)):0,last=rows.length?rows[rows.length-1]:null;
  box.innerHTML=`<div class="progress-mini-grid"><article><small>Mock Attempts</small><strong>${rows.length}</strong></article><article><small>Average Score</small><strong>${avg}%</strong></article><article><small>Best Score</small><strong>${best}%</strong></article></div><p class="muted">${last?"पछिल्लो अभ्यास: "+last.percent+"% • "+new Date(last.date).toLocaleDateString():"अहिलेसम्म NHPC Mock Test को नतिजा छैन। पहिलो परीक्षा दिएपछि यहाँ प्रगति देखिन्छ।"}</p>`;
 }
 renderNhpcProgress();
 // NHPC mock options: 50, 100, 150, or the complete available question bank.
 const mockRoot=document.getElementById("nhpcFullMock");
 let mockSet=[],mockAt=0,mockPicked={},mockClock=null,mockSeconds=3600,mockDone=false,mockTarget=50;
 const shuffleItems=a=>[...a].sort(()=>Math.random()-.5);
 function openNhpcMock(){
  clearInterval(mockClock);mockClock=null;
  mockRoot.classList.remove("hidden");
  document.getElementById("nhpcCloseMock")?.classList.remove("hidden");
  document.getElementById("nhpcMcqArea")?.classList.add("hidden");
  document.getElementById("nhpcCloseMcq")?.classList.add("hidden");
  const total=mockBank.length;
  mockRoot.innerHTML=`<div class="section-head"><div><p class="eyebrow">PCL IN DENTAL HYGIENE • NHPC</p><h3>Mock Test छान्नुहोस्</h3></div><span class="pill">${total} प्रश्न उपलब्ध</span></div>
   <div class="notice"><b>आफ्नो परीक्षा अभ्यास छान्नुहोस्</b><p>प्रत्येक प्रश्न १ अंक। प्रश्नहरू उपलब्ध question bank बाट random रूपमा छानिन्छन् र सही उत्तरको स्थान पनि परिवर्तन हुन्छ।</p></div>
   <div class="feature-grid" style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">
    <button class="feature-card" data-mock-size="50"><b>Mini Mock</b><strong>५० प्रश्न</strong><small>६० मिनेट</small></button>
    <button class="feature-card" data-mock-size="100"><b>Standard Mock</b><strong>१०० प्रश्न</strong><small>१२० मिनेट</small></button>
    <button class="feature-card" data-mock-size="150"><b>Advanced Mock</b><strong>१५० प्रश्न</strong><small>१८० मिनेट</small></button>
    <button class="feature-card" data-mock-size="all"><b>Full Question Bank</b><strong>${total} प्रश्न</strong><small>${Math.ceil(total*1.2)} मिनेट</small></button>
   </div>
   <p class="muted">समय प्रति प्रश्न १.२ मिनेटका आधारमा राखिएको छ। यो अभ्यासको नमुना ढाँचा हो, NHPC को आधिकारिक परीक्षा ढाँचा होइन।</p>`;
  mockRoot.scrollIntoView({behavior:"smooth",block:"start"});
  mockRoot.querySelectorAll("[data-mock-size]").forEach(b=>b.addEventListener("click",()=>{mockTarget=b.dataset.mockSize==="all"?total:Number(b.dataset.mockSize);beginNhpcMock()}));
 }
 function beginNhpcMock(){
  clearInterval(mockClock);mockSet=shuffleItems(mockBank).slice(0,Math.min(mockTarget,mockBank.length));mockAt=0;mockPicked={};mockSeconds=Math.ceil(mockSet.length*72);mockDone=false;drawNhpcMock();
  mockClock=setInterval(()=>{mockSeconds--;const t=mockRoot.querySelector("#nhpcFullTimer");if(t)t.textContent=fmtNhpcTime();if(mockSeconds<=0)finishNhpcMock(true)},1000);
 }
 function fmtNhpcTime(){return Math.floor(mockSeconds/60)+":"+String(mockSeconds%60).padStart(2,"0")}
 function drawNhpcMock(){
  const total=mockSet.length,item=mockSet[mockAt],q=item.q,selected=mockPicked[mockAt];
  mockRoot.innerHTML=`<div class="section-head"><div><p class="eyebrow">PCL DENTAL HYGIENE MOCK TEST</p><h3>प्रश्न ${mockAt+1} / ${total}</h3></div><span class="timer" id="nhpcFullTimer">${fmtNhpcTime()}</span></div>
   <div class="mock-progress"><span style="width:${Object.keys(mockPicked).length/total*100}%"></span></div>
   <div class="mock-nav" aria-label="Question navigation">${mockSet.map((_,i)=>`<button type="button" class="${i===mockAt?"current":""} ${mockPicked[i]!==undefined?"answered":""}" data-jump="${i}">${i+1}</button>`).join("")}</div>
   <article class="question"><div class="qtop"><span>${item.topic}</span><span>${selected===undefined?"उत्तर छान्नुहोस्":"उत्तर सुरक्षित भयो"}</span></div><h3>${q[0]}</h3><p class="translation">${q[1]}</p><div class="options">${q[2].map((o,i)=>`<button type="button" class="option ${selected===i?"selected":""}" data-full-answer="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join("")}</div>
   <div class="nextrow"><button class="smallbtn" id="nhpcFullPrev" ${mockAt===0?"disabled":""}>अघिल्लो</button><span class="muted">${Object.keys(mockPicked).length}/${total} उत्तर</span><button class="smallbtn" id="nhpcFullNext">${mockAt===total-1?"परीक्षा बुझाउनुहोस्":"अर्को"}</button></div></article>
   <div class="nextrow"><button class="secondary" id="nhpcFullSubmit">अहिले नै परीक्षा बुझाउनुहोस्</button></div>`;
  mockRoot.querySelectorAll("[data-full-answer]").forEach(b=>b.addEventListener("click",()=>{mockPicked[mockAt]=Number(b.dataset.fullAnswer);drawNhpcMock()}));
  mockRoot.querySelectorAll("[data-jump]").forEach(b=>b.addEventListener("click",()=>{mockAt=Number(b.dataset.jump);drawNhpcMock()}));
  mockRoot.querySelector("#nhpcFullPrev").addEventListener("click",()=>{mockAt=Math.max(0,mockAt-1);drawNhpcMock()});
  mockRoot.querySelector("#nhpcFullNext").addEventListener("click",()=>{if(mockAt===total-1)finishNhpcMock(false);else{mockAt++;drawNhpcMock()}});
  mockRoot.querySelector("#nhpcFullSubmit").addEventListener("click",()=>{if(confirm("परीक्षा बुझाउने हो? बाँकी अनुत्तरित प्रश्न गलत मानिनेछन्।"))finishNhpcMock(false)});
 }
 function finishNhpcMock(auto){
  if(mockDone)return;mockDone=true;clearInterval(mockClock);mockClock=null;
  const total=mockSet.length,answered=Object.keys(mockPicked).length,score=mockSet.reduce((sum,item,i)=>sum+(mockPicked[i]===item.q[3]?1:0),0),percent=Math.round(score/total*100);
  window.DHPNProgress?.recordMock?.("PCL in Dental Hygiene",score,total);renderNhpcProgress();
  mockRoot.innerHTML=`<div class="result"><p>PCL IN DENTAL HYGIENE MOCK COMPLETED</p><strong>${score}/${total}</strong><b>${percent}%</b><p>${auto?"समय सकिएपछि परीक्षा स्वतः बुझाइयो।":"तपाईंको परीक्षा बुझाइयो।"} ${total-answered} प्रश्न अनुत्तरित थिए।</p><p>${percent>=80?"धेरै राम्रो प्रयास!":percent>=50?"राम्रो प्रयास। कमजोर विषयहरू पुनः अध्ययन गर्नुहोस्।":"नोट्स पढेर फेरि अभ्यास गर्नुहोस्।"}</p><button class="primary" id="nhpcShowReview">उत्तर समीक्षा गर्नुहोस्</button> <button class="secondary" id="nhpcRetake">फेरि परीक्षा दिनुहोस्</button></div><div id="nhpcFullReview"></div>`;
  mockRoot.querySelector("#nhpcShowReview").addEventListener("click",()=>{mockRoot.querySelector("#nhpcFullReview").innerHTML=mockSet.map((item,i)=>{const q=item.q,ans=mockPicked[i];return `<article class="note"><p class="eyebrow">${i+1}. ${item.topic}</p><h3>${q[0]}</h3><p class="translation">${q[1]}</p><p>तपाईंको उत्तर: <b>${ans===undefined?"उत्तर नदिएको":q[2][ans]}</b></p><p>सही उत्तर: <b>${q[2][q[3]]}</b></p><p>${q[4]}</p><p class="np">${q[5]}</p><span class="pill">${ans===q[3]?"सही":"गलत / अनुत्तरित"}</span></article>`}).join("")});
  mockRoot.querySelector("#nhpcRetake").addEventListener("click",openNhpcMock);
 }
 document.getElementById("nhpcStartFullMock")?.addEventListener("click",openNhpcMock);
 document.getElementById("nhpcCloseMock")?.addEventListener("click",()=>{clearInterval(mockClock);mockClock=null;mockRoot.classList.add("hidden");document.getElementById("nhpcCloseMock")?.classList.add("hidden")});


